// Les secondes qui restent avant `fin` (ms), et un rendu par seconde tant qu'il
// en reste. 0 = plus d'attente.
const useSecondesRestantes = (fin) => {
  const [, tic] = React.useState(0);
  React.useEffect(() => {
    if (!(fin > Date.now())) return undefined;
    const t = setInterval(() => { tic((x) => x + 1); if (Date.now() >= fin) clearInterval(t); }, 1000);
    return () => clearInterval(t);
  }, [fin]);
  return fin > Date.now() ? Math.ceil((fin - Date.now()) / 1000) : 0;
};
const authSignUp  = async (email, password) => {
  const r = await authCall(avecRetour('signup'), { email: String(email).trim().toLowerCase(), password });
  if (!r.ok) {
    if(r.captcha)return {ok:false,error:r.error};
    // On traduit les erreurs techniques de Supabase : « email rate limit
    // exceeded » ne veut rien dire pour quelqu'un qui essaie juste de créer un
    // compte, alors que la cause est précise et la solution simple.
    let msg = r.error;
    const attente = delaiDemandeEmail(r.error);
    if (attente) return { ok: false, error: texteDelaiEmail(attente), attente };
    if (/already registered/i.test(r.error)) msg = 'Un compte existe déjà avec cet email.';
    else if (/rate limit/i.test(r.error)) msg = MAIL_QUOTA;
    else if (/invalid/i.test(r.error) && /email/i.test(r.error)) msg = 'Cette adresse email est refusée par le serveur.';
    else if (/signups? not allowed|disabled/i.test(r.error)) msg = 'Les inscriptions sont fermées pour le moment.';
    return { ok: false, incertain:r.status===0 || r.status>=500, error: r.status===0 || r.status>=500 ? 'Je ne peux pas confirmer le résultat de la création. Si tu as reçu un email VRM, ton compte peut déjà être créé : confirme-le, puis utilise « Se connecter » ici.' : msg };
  }
  if(!r.json?.access_token && !r.json?.id && !r.json?.user?.id)return {ok:false,incertain:true,error:'La réponse du serveur est incomplète. Si tu as reçu un email, confirme-le puis connecte-toi ici ; sinon réessaie dans un instant.'};
  // Si la confirmation par email est activée côté Supabase, il n'y a pas encore
  // de jeton : le compte n'existe vraiment qu'une fois le lien cliqué.
  if (r.json && r.json.access_token) { writeSession(sessionFrom(r.json)); return { ok: true }; }
  return { ok: true, needsConfirm: true };
};
const authReset   = (email) => authCall(avecRetour('recover', '/recuperation.html'), { email: String(email).trim().toLowerCase() });

// ── CONNEXION AVEC GOOGLE / DISCORD (OAuth, méthode PKCE) ─────────────────
// Comment ça marche : on n'échange JAMAIS de mot de passe. On envoie le vendeur
// chez Google (ou Discord), qui l'identifie et renvoie un code à usage unique.
// L'app échange ce code contre une session.
//
// Pourquoi PKCE et pas la méthode « implicite » (plus simple à écrire) : en
// implicite, le jeton d'accès revient DANS L'URL. Il finit dans l'historique du
// navigateur, dans les journaux d'un proxy d'entreprise, dans le presse-papier
// si on copie le lien. En PKCE il ne revient qu'un code inutilisable seul :
// pour l'échanger il faut aussi le « vérificateur », un secret aléatoire tiré
// par l'app, gardé dans cet onglet et jamais transmis à personne d'autre.
// Résultat : intercepter l'URL ne suffit plus à voler la session.
const PKCE_KEY = 'vrm_pkce';
// Le lien « mot de passe oublié » connecte techniquement le vendeur, mais il
// n'a pas encore choisi son nouveau mot de passe : sans ce drapeau, l'app
// s'ouvrirait normalement et il ne verrait jamais le formulaire.
let RECOVERY_PENDING = false;
const b64url = (bytes) => btoa(String.fromCharCode(...new Uint8Array(bytes))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const makeVerifier = () => { const a = new Uint8Array(48); crypto.getRandomValues(a); return b64url(a); };
const makeChallenge = async (v) => b64url(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(v)));

const OAUTH_PROVIDERS = [
  { id: 'google',  label: 'Google' },
  { id: 'discord', label: 'Discord' },
];

// ── CE QUE LA BASE ACCEPTE VRAIMENT ───────────────────────────────────────
// Supabase publie ses réglages d'authentification. On les lit AVANT d'afficher
// quoi que ce soit, pour ne jamais proposer un bouton qui ne peut pas marcher.
// Sans ça, « Continuer avec Google » quittait l'app pour afficher une page
// noire avec du JSON brut — l'utilisateur se retrouvait dehors, devant un
// message d'erreur technique, sans bouton retour.
let AUTH_SETTINGS = null;
const loadAuthSettings = async () => {
  try {
    const r = await fetch(`${SUPABASE_URL}/auth/v1/settings`, { headers: { apikey: SUPABASE_KEY },signal:AbortSignal.timeout(15000) });
    if (r.ok) { AUTH_SETTINGS = await r.json(); _emitAuth(); }  // réveille l'écran de connexion
  } catch (_) {}
  return AUTH_SETTINGS;
};
// Un fournisseur n'est proposé que s'il est réellement activé côté Supabase.
const providerEnabled = (id) => !!(AUTH_SETTINGS && AUTH_SETTINGS.external && AUTH_SETTINGS.external[id]);
// La création de compte attend-elle un email de confirmation ? Si oui, on le
// dit AVANT que la personne tape son mot de passe.
const confirmRequired = () => !!(AUTH_SETTINGS && AUTH_SETTINGS.mailer_autoconfirm === false);

const oauthStart = async (provider) => {
  try {
    try{sessionStorage.removeItem('vrm_oauth_liaison');localStorage.removeItem('vrm_oauth_liaison');}catch(_){}
    const verifier = makeVerifier();
    sessionStorage.setItem(PKCE_KEY, verifier);          // cet onglet
    // Téléphone : l'app Discord/Google renvoie souvent le retour dans un NOUVEL
    // onglet (sessionStorage vide) — le vérificateur est aussi gardé 10 min sur
    // l'appareil. Seul, il ne sert à rien : il faut aussi le code du retour.
    try { localStorage.setItem(PKCE_KEY, JSON.stringify({ v: verifier, at: Date.now() })); } catch (_) {}
    const challenge = await makeChallenge(verifier);
    const url = `${SUPABASE_URL}/auth/v1/authorize?provider=${encodeURIComponent(provider)}`
      + `&redirect_to=${encodeURIComponent(window.location.origin + window.location.pathname)}`
      + `&code_challenge=${encodeURIComponent(challenge)}&code_challenge_method=s256`;
    window.location.href = url;
    return { ok: true };
  } catch (e) { return { ok: false, error: "Impossible d'ouvrir la connexion " + provider + '.' }; }
};

const lireConnexionsOAuth = async()=>{
 try{const r=await fetch(`${SUPABASE_URL}/auth/v1/user`,{headers:{apikey:SUPABASE_KEY,...enTeteSession()},signal:AbortSignal.timeout(15000)});if(!r.ok)return null;const j=await r.json();return Array.isArray(j.identities)?j.identities.map(i=>i.provider):null;}catch(_){return null;}
};
const oauthRelier = async provider => {
  try{const verifier=makeVerifier();const r=await preparerLiaisonOAuth({provider,enabled:providerEnabled(provider),token:AUTH.session?.access_token,owner:AUTH.user?.id,base:SUPABASE_URL,cle:SUPABASE_KEY,origine:window.location.origin,verifier,challenge:await makeChallenge(verifier)});if(r.ok)window.location.assign(r.url);return r;}catch(_){return{ok:false,error:'Impossible de préparer cette connexion. Réessaie.'};}
};

// Au retour du fournisseur. Deux formes possibles :
//  • ?code=…            → OAuth en PKCE (Google, Discord) : on échange le code
//  • #access_token=…    → lien reçu par email (mot de passe oublié)
// Dans les deux cas on NETTOIE l'URL derrière nous : un jeton ne doit pas
// rester dans la barre d'adresse ni partir dans l'historique.
const cleanAuthUrl = () => {
  try { window.history.replaceState({}, '', window.location.pathname + window.location.search.replace(/[?&](code|error|error_description|error_code)=[^&]*/g, '').replace(/^&/, '?')); } catch (_) {}
  try { if (window.location.hash) window.history.replaceState({}, '', window.location.pathname + window.location.search); } catch (_) {}
};
const consumeAuthRedirect = async () => {
  if (!MULTI_USER) return null;
  const q = new URLSearchParams(window.location.search);
  const hash = new URLSearchParams((window.location.hash || '').replace(/^#/, ''));

  const err = q.get('error_description') || q.get('error') || hash.get('error_description') || hash.get('error');
  if (err) { lireLiaisonOAuth(sessionStorage,localStorage); cleanAuthUrl(); return { error: decodeURIComponent(String(err).replace(/\+/g, ' ')) }; }

  const code = q.get('code');
  if (code) {
    const liaison=lireLiaisonOAuth(sessionStorage,localStorage);
    let verifier = liaison?.verifier || sessionStorage.getItem(PKCE_KEY);
    sessionStorage.removeItem(PKCE_KEY);
    try {
      const o = JSON.parse(localStorage.getItem(PKCE_KEY) || 'null');
      localStorage.removeItem(PKCE_KEY);
      if (!verifier && o && typeof o.v === 'string' && Date.now() - Number(o.at) <= 10 * 60 * 1000) verifier = o.v;
    } catch (_) {}
    cleanAuthUrl();
    if (!verifier) return { error: 'Connexion expirée, réessaie depuis cet appareil.' };
    const r = await authCall('token?grant_type=pkce', { auth_code: code, code_verifier: verifier });
    if (!r.ok) return { error: r.error };
    if(!resultatLiaisonPermis(liaison,r.json))return{error:'La liaison ne correspond pas à ton compte VRM. Ta session a été conservée.'};
    writeSession(sessionFrom(r.json));
    return { ok: true, liaison:liaison?.provider };
  }

  const at = hash.get('access_token');
  if (at) {
    const type = hash.get('type');
    const sess = {
      access_token: at,
      refresh_token: hash.get('refresh_token') || '',
      expires_at: Date.now() + ((parseInt(hash.get('expires_in') || '3600', 10)) * 1000),
      user: null,
    };
    cleanAuthUrl();
    AUTH = { ...AUTH, session: sess };
    const me = await fetchMe(at);                        // qui es-tu ?
    writeSession({ ...sess, user: me ? { id: me.id, email: me.email } : null, ...(me ? { totp: me._totp, totpNoms: me._totpNoms } : {}) });
    if (type === 'recovery') RECOVERY_PENDING = true;
    return { ok: true, recovery: type === 'recovery' };
  }
  return null;
};

// Le jeton ne dit pas l'email en clair : on demande à Supabase qui il désigne.
const fetchMe = async (token) => {
  try {
    const res = await fetch(`${SUPABASE_URL}/auth/v1/user`, { headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${token}` } });
    if (!res.ok) return null;
    const j = await res.json();
    // `_totp` : les facteurs TOTP vérifiés (double vérification), rangés à part
    // dans la session par l'appelant — jamais dans `user`.
    return { id: j.id, email: j.email, _totp: totpVerifies(j), _totpNoms: totpNoms(j) };
  } catch (_) { return null; }
};

// Changer son adresse email. Supabase envoie une confirmation aux DEUX adresses
// (l'ancienne et la nouvelle) quand « Secure email change » est actif : tant que
// les deux liens ne sont pas ouverts, l'ancienne reste la bonne. On le dit.
const authSetEmail = async (email) => {
  const tok = AUTH.session && AUTH.session.access_token;
  if (!tok) return { ok: false, error: 'Reconnecte-toi avant de changer ton email.' };
  try {
    // Le lien de validation de la nouvelle adresse ramène sur l'app (`avecRetour`).
    const res = await fetch(`${SUPABASE_URL}/auth/v1/${avecRetour('user')}`, {
      method: 'PUT',
      headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${tok}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: String(email).trim().toLowerCase() }),
    });
    const j = await res.json().catch(() => ({}));
    if (!res.ok) { const brut = j.msg || j.message || `Erreur ${res.status}`; return { ok: false, error: mapMailError(brut), attente: delaiDemandeEmail(brut) }; }
    return { ok: true };
  } catch (_) { return { ok: false, error: 'Pas de connexion internet.' }; }
};

// Choisir un nouveau mot de passe (après le lien « mot de passe oublié »).
const authSetPassword = async (password) => {
  const tok = AUTH.session && AUTH.session.access_token;
  if (!tok) return { ok: false, error: 'Lien expiré, redemande un email.' };
  try {
    const res = await fetch(`${SUPABASE_URL}/auth/v1/user`, {
      method: 'PUT',
      headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${tok}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ password }),
    });
    const j = await res.json().catch(() => ({}));
    if (!res.ok) return { ok: false, error: j.msg || j.message || 'Mot de passe refusé.' };
    return { ok: true };
  } catch (_) { return { ok: false, error: 'Pas de connexion internet.' }; }
};
// « Se déconnecter » (un GESTE) déconnecte aussi l'extension de ce Chrome —
// adressé, et seulement si elle écrit sous CE compte. Une session qui meurt
// toute seule, elle, ne fait plus rien oublier à l'extension (11 octobre).
const authSignOut = () => {
  const uid = AUTH.user && AUTH.user.id;
  try { if (uid) deconnecterExtension(String(uid)); } catch (_) {}
  // ⚠️ Revue du 11 octobre : une extension d'avant la 5.171 n'entend pas le
  //    canal adressé — après « Se déconnecter », elle continuait d'écrire sous
  //    ce compte (mesuré : aucun message envoyé ; la modale promet pourtant
  //    qu'« une autre personne qui se connecte derrière toi n'hérite pas de tes
  //    numéros »). Sur ce GESTE seulement, l'ancien message (`session: null`).
  //    Pas quand on SAIT qu'elle écrit sous un AUTRE compte : ce n'est pas la
  //    nôtre à déconnecter. Deux copies (une neuve, une ancienne) : l'ancienne
  //    aussi doit oublier — la neuve ignore ce message.
  try {
    if (uid && (extSait('liaison') !== 'ok' || __vmrPlusieurs)) {
      const v = __vmrEtat && __vmrEtat.ok ? __vmrEtat.vrm : null;
      const sonId = String((v && v.user_id) || ''), sonMail = String((v && v.email) || '').trim().toLowerCase();
      const monMail = String((AUTH.user && AUTH.user.email) || '').trim().toLowerCase();
      const autre = !!v && v.connecte === true && ((sonId && sonId !== String(uid)) || (!sonId && sonMail && monMail && sonMail !== monMail));
      if (!autre) deconnecterExtensionAncienne();
    }
  } catch (_) {}
  writeSession(null); wipeLocalData();
};

// CHANGEMENT DE VENDEUR SUR LE MÊME NAVIGATEUR : le localStorage est commun à
// tout le site. Sans ménage, le vendeur qui se connecte après un autre
// hériterait de ses numéros, de son garage et — pire — les repousserait dans
// le cloud sous SON compte. On efface donc toutes les clés de données quand
// l'identité change (on garde les préférences d'affichage, elles ne trahissent
// personne).
const KEEP_ON_SWITCH = ['vinted_dark', SESSION_KEY, 'schema_cloisonne'];
const wipeLocalData = () => {
  try {
    const doomed = [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k) continue;
      if (KEEP_ON_SWITCH.includes(k)) continue;
      if (/^(vinted_|vrm_|cancale)/.test(k)) doomed.push(k);
    }
    doomed.forEach(k => localStorage.removeItem(k));
  } catch (_) {}
  // La réserve des QR de Ma journée hors ligne part avec les photos (`vrm_hl_photo_*`).
  try { if (typeof caches !== 'undefined') caches.delete(CACHE_QR).catch(() => {}); } catch (_) {}
};
// Mémorise à qui appartiennent les données présentes dans ce navigateur.
const OWNER_MARK = 'vrm_local_owner';
const ensureLocalOwner = (uid) => {
  try {
    const prev = localStorage.getItem(OWNER_MARK);
    if (prev !== uid) wipeLocalData();          // ce n'était pas toi → on repart propre
    if (prev !== uid) localStorage.setItem(OWNER_MARK, uid);
  } catch (_) {}
};

// Restaure la session au démarrage, et renouvelle le jeton s'il a expiré.
let AUTH_REDIRECT = null;   // résultat du retour OAuth / lien email, lu par l'écran de connexion
const authBoot = async () => {
  // ⚠️ NE PAS BLOQUER LE PREMIER AFFICHAGE SUR LE RÉSEAU.
  // Avant, on attendait DEUX appels réseau ici : l'app restait sur un écran
  // vide tant que Supabase n'avait pas répondu — mesuré à plus de 13 s dès que
  // la connexion traîne. C'est ça, « le chargement est beaucoup trop long ».
  // • Les moyens de connexion (Google/Discord) ne servent qu'à dessiner deux
  //   boutons sur l'écran de connexion : on les charge SANS attendre, et
  //   `loadAuthSettings` redessine l'écran quand la réponse arrive.
  // • `detectSchema` décide comment on ÉCRIT (cloisonné ou non) : on l'attend,
  //   mais avec une limite de temps, sinon un réseau qui pend fige l'app.
  //   Au-delà, on garde le comportement d'aujourd'hui (non cloisonné), qui est
  //   le repli sûr décrit dans CLAUDE.md.
  if (MULTI_USER) loadAuthSettings();
  // Base déjà connue comme cloisonnée sur cet appareil : on ne l'attend plus
  // (la sonde tourne en fond). Sinon on l'attend un peu plus longtemps — ses
  // trois essais servent justement les jours où la base traîne.
  if (CLOISONNE) detectSchema();
  else await Promise.race([detectSchema(), new Promise(r => setTimeout(r, 6000))]);
  if (!MULTI_USER) { AUTH = { ...AUTH, ready: true }; prechargerDemarrage(); _emitAuth(); return; }
  // Retour de Google / Discord / d'un lien email : ça prime sur tout le reste.
  try { AUTH_REDIRECT = await consumeAuthRedirect(); } catch (_) { AUTH_REDIRECT = null; }
  if (AUTH_REDIRECT && AUTH_REDIRECT.ok && !AUTH_REDIRECT.recovery) { AUTH = { ...AUTH, ready: true }; _emitAuth(); return; }
  const s = readSession();
  if (!s) { AUTH = { ...AUTH, ready: true }; prechargerDemarrage(); _emitAuth(); return; }
  AUTH = { ...AUTH, session: s, user: s.user || null };
  // ⚠️ Une coupure réseau à l'ouverture ne déconnecte plus (18 octobre) : seul
  // un REFUS du service (false) efface la session. « Pas su » (null) garde la
  // session ; la minuterie et le réveil réessaient le renouvellement.
  if (!authValid()) { const ok = await authRefresh(); if (ok === false) { writeSession(null); return; } }
  AUTH = { ...AUTH, ready: true };
  if (AUTH.user && AUTH.user.id) ensureLocalOwner(AUTH.user.id);
  prechargerDemarrage();
  _emitAuth();
};
// ── LE PREMIER ÉCRAN N'ATTEND PLUS SON PROPRE RENDU (16 octobre) ─────────────
// Mesuré au banc `vitesse.cjs` (téléphone, processeur ×4) : Ma journée enchaînait
// sonde de schéma → (rendu d'AppCoeur, ~600 ms de processeur) → comptes →
// (rendu, ~350 ms) → ventes. Les comptes et les ventes ne dépendent d'aucun rendu :
// ils partent ici, dès que la porte sait qu'AppCoeur va monter, et AppCoeur /
// `loadOrders` reprennent les MÊMES lectures (mêmes fonctions, même `cachedRow`).
// ⚠️ Les gardes ne bougent pas — on part aux mêmes conditions qu'AppCoeur :
//   · avec une session : le jeton du vendeur (`sbAuth`), quelle que soit la base ;
//   · sans session : seulement si la porte laisse passer (accès direct) ET que la
//     sonde a MESURÉ une base non cloisonnée pendant cette ouverture — jamais sur
//     un repli, jamais une lecture anonyme sur une base cloisonnée ;
//   · rien pendant une récupération de mot de passe (la porte montre la connexion).
// Un échec rend `null` comme avant (`fetchVintedAccounts`) : AppCoeur dit la panne,
// jamais « aucun compte ». Le préchargement n'est repris qu'une fois, par le même
// vendeur, dans les 30 s ; sinon AppCoeur relit.
let _confidentialiteUid='';
let _prechargeComptes = null;   // { at, qui, promesse }
const prechargerDemarrage = () => {
  try {
    if (typeof window === 'undefined' || _prechargeComptes) return;
    if(MULTI_USER&&(!AUTH.user?.id||_confidentialiteUid!==AUTH.user.id))return;
    if (MULTI_USER) {
      if (RECOVERY_PENDING) return;
      const session = !!(AUTH.session && AUTH.session.access_token && AUTH.user);
      // Double vérification pas encore passée : la porte du code est fermée,
      // aucune donnée du vendeur ne se lit avant (AppCoeur relira après le code).
      if (session && !mfaPasse()) return;
      if (!session) {
        const direct = (() => { try { return localStorage.getItem('vrm_acces_direct') === '1'; } catch (_) { return false; } })();
        if (!(direct && SCHEMA_MESURE && !CLOISONNE)) return;
      }
    }
    const qui = (AUTH.user && AUTH.user.id) || 'local';
    const promesse = fetchVintedAccounts();
    // Les commandes de TOUS les comptes en une lecture, EN MÊME TEMPS que la liste
    // des comptes (on ne connaît pas encore leurs identifiants). ⚠️ Au premier
    // rendu, le processeur est pris par AppCoeur : une lecture lancée « dès que
    // la liste arrive » ne partait qu'après lui (mesuré : +500 ms au téléphone).
    // `strict` : une page ratée vaut « pas su » (null), jamais une demi-liste.
    const famille = lireTout('id=like.harvest_*_orders_*&select=id,data,updated_at,cap:data->>capturedAt', { strict: true }).catch(() => null);
    _prechargeComptes = { at: Date.now(), qui, promesse };
    // Dès que la liste arrive, chaque compte LIÉ reçoit SA part — exactement les
    // lignes que `fetchHarvestOrdersBrut(uid)` aurait rendues (même préfixe) —
    // dans `cachedRow('o:uid')`, où `loadOrders` la retrouve. Un compte retiré
    // n'est jamais servi (on ne part que de la liste). Famille illisible ⇒ la
    // lecture par compte d'avant, dans la même entrée de cache.
    promesse.then((list) => {
      if (!Array.isArray(list)) return;
      for (const a of list) {
        const uid = a && a.vinted_user_id; if (!uid) continue;
        const pre = `harvest_${uid}_orders_`;
        try { cachedRow(`o:${uid}`, () => famille.then((rows) => Array.isArray(rows) ? rows.filter((r) => String(r && r.id).startsWith(pre)) : fetchHarvestOrdersBrut(uid))).catch(() => {}); } catch (_) {}
      }
    }).catch(() => {});
  } catch (_) { _prechargeComptes = null; }
};
const prendrePrechargeComptes = () => {
  const e = _prechargeComptes; _prechargeComptes = null;
  if (!e || (Date.now() - e.at) > 30000) return null;
  if (e.qui !== ((AUTH.user && AUTH.user.id) || 'local')) return null;
  return e.promesse;
};
// Renouvellement périodique tant que l'app est ouverte.
if (MULTI_USER && typeof window !== 'undefined') {
  setInterval(() => { if (AUTH.session && !authValid()) authRefresh(); }, 4 * 60 * 1000);
  // Au réveil : une minuterie ne tourne pas pendant la veille de l'ordinateur.
  const auReveil = () => { try { if (AUTH.session && !authValid() && (typeof document === 'undefined' || document.visibilityState !== 'hidden')) authRefresh(); } catch (_) {} };
  try { document.addEventListener('visibilitychange', auReveil); window.addEventListener('focus', auReveil); window.addEventListener('online', auReveil); } catch (_) {}
}

// L'EXTENSION A BESOIN DE SAVOIR QUI TU ES.
// Elle écrit dans la même base (annonces, ventes, messages captés au passage).
// Une fois l'isolation activée, la clé publique n'a plus le droit d'écrire :
// il faut qu'elle écrive sous TON compte.
// ⚠️⚠️ L'APP NE LUI PRÊTE PLUS SA PROPRE SESSION (5 octobre). Jusqu'ici on lui
//    envoyait NOTRE jeton de renouvellement à chaque changement et à chaque
//    « ready » : l'app et l'extension renouvelaient alors la MÊME famille de
//    jetons. Avec la rotation de Supabase, la seconde qui renouvelle présente
//    un jeton déjà consommé — mesuré dans les journaux d'authentification de
//    la production le 5 octobre : `refresh_token_already_used`, puis une
//    rafale de 429. L'extension perdait sa session (« l'extension ne répond
//    pas » sur le bouton du bordereau), et l'app risquait la sienne.
//    ⇒ L'extension reçoit SA session, fabriquée par le serveur pour le même
//      compte (`/api/compte?mode=session-extension`) : deux familles de jetons
//      indépendantes, qui ne se marchent plus dessus. On ne la lui donne que
//      quand elle en a BESOIN (pas de session, session morte, autre compte),
//      jamais à chaque rafraîchissement. Voir `assurerSessionExtension`.
// ⚠️⚠️ 11 OCTOBRE — PLUS AUCUNE SESSION PAR LA PAGE, ET JAMAIS LA NÔTRE.
//    Mesuré dans les journaux d'authentification de production, et rejoué sur
//    un vrai GoTrue (relectures du 11 octobre) :
//    · `window.postMessage({__vmr:'session'})` est entendu par TOUTE extension
//      de la page — une copie ancienne restée à côté adoptait la même famille
//      de jetons, qui finit révoquée (« Possible abuse attempt ») ;
//    · un `session: null` posté au démarrage d'une app dont la session venait de
//      mourir faisait OUBLIER à l'extension la sienne, saine (9 oct. 18:37,
//      10 oct. 09:08 : une écriture, puis plus rien — « à chaque fois je dois
//      me reconnecter ») ;
//    · `legacySessionExtension` prêtait à une extension < 5.129 NOTRE propre
//      jeton de renouvellement (rejoué : famille révoquée, l'app perd sa
//      session 12 s plus tard).
//    ⇒ La session de l'extension est ADRESSÉE à UNE extension, par son
//      identifiant (`chrome.runtime.sendMessage(<id>, …)`, permis par
//      `externally_connectable`), avec un NONCE qu'elle a elle-même émis, et
//      fabriquée par le serveur pour le même compte (une famille de jetons à
//      elle). Voir `assurerSessionExtension`. Une extension d'avant la 5.171
//      (sa 5.164, la 5.170 de production) n'entend pas ce canal : elle reçoit,
//      seule et quand elle en a besoin, une session fabriquée par le serveur par
//      l'ancien message de la page (`sessionParLaPage` — relecture croisée de
//      la 5.174 : sans ça, elle n'était plus jamais reconnectée).
//    ⇒ Une session de l'app qui MEURT ne touche plus à celle de l'extension.
//      Seul « Se déconnecter » (un geste) la déconnecte, et seulement si elle
//      écrit sous CE compte (`deconnecterExtension`).
// ⚠️⚠️ DEUX EXTENSIONS VRM DANS LE MÊME CHROME (mesuré le 9 octobre, 5.165) :
//    `null` = une seule répond (ou pas su) · `['5.77.0','5.165.0']` = PLUSIEURS.
//    Décidé par `sonderPonts` (plus bas), lu par `raisonExtGlobale`, `vmrExec`,
//    `vmrDemande` et `assurerSessionExtension`.
let __vmrPlusieurs = null;
let __sessionAvait = false;
if (MULTI_USER && typeof window !== 'undefined') {
  onAuthChange(() => {
    const a = !!(AUTH.session && AUTH.user);
    __sessionAvait = a;
    // Connexion (ou nouveau compte) : on vérifie si l'extension a ce qu'il faut.
    // ⚠️ Double vérification : pas avant le code — sinon le mot de passe seul
    //    donnerait une session à l'extension (`mfaPasse`).
    if (a && mfaPasse()) setTimeout(() => { try { assurerSessionExtension(); } catch (_) {} }, 50);
  });
}

