//    widget — `scripts/audit-statuts.cjs` les exécute toutes sur le même corpus.
const PAS_UN_ENVOI = /annul|cancel|refus|rembours|retour|suspend|finalis|paiement\s+a\s+[ée]chou|[ée]chec\s+du\s+paiement/i;
const tusDe = (o) => String((o && o.transaction_user_status) || '').toLowerCase();
// Une VENTE dont le colis REVIENT vers le vendeur : l'acheteur ne l'a pas retiré
// (« non réclamée »), ou il a ouvert un retour. Rangée « annulée » pour l'ARGENT
// (`classifyOrderStatus` : aucun CA), mais c'est un colis en route qu'il faut
// surveiller — pas une vente qui n'a pas eu lieu. Même partition que les
// étiquettes « Retournée » / « Retour en cours » (`venteStage`).
const venteQuiRevient = (o) => /non\s+r[ée]clam|retour\s+initi|retour\s+en\s+cours|retour\s+demand/i.test(String((o && o.status) || ''));
// ⚠️ `needs_action` VEUT DIRE « UNE ACTION », PAS « EXPÉDIE » (17 oct.).
// Mesuré : la vente en litige nB546 portait `needs_action` avec le statut
// « colis déposé en bureau de Poste ou point relais » — le colis de RETOUR,
// l'action attendue étant « marquer comme reçu ». Un statut qui dit que le colis
// a déjà bougé (déposé, expédié, en transit, livré, non réclamé) n'est jamais un
// colis à poster, quel que soit le champ machine. Les 14 autres `needs_action`
// de sa base (« Bordereau envoyé au vendeur », « Le paiement a été validé ») ne
// sont pas touchés. MÊME RÈGLE dans le widget et l'extension (§11).
const COLIS_DEJA_BOUGE = /d[ée]pos[ée]|exp[ée]di[ée]|achemin|transit|livr[ée]e?\b|non\s+r[ée]clam|r[ée]ceptionn/i;
const aExpedier = (o) => {
  if (!o) return false;
  const s = String(o.status || '');
  if (PAS_UN_ENVOI.test(s)) return false;
  // Le détail de la transaction, plus frais que la liste (litige, retour,
  // suspension, annulation, finalisée) : jamais un colis à poster.
  if (o.transaction_id != null && txnBloqueEnvoi(o.transaction_id)) return false;
  const t = tusDe(o);
  if (t === 'needs_action') return !COLIS_DEJA_BOUGE.test(s);
  if (t === 'waiting' || t === 'completed' || t === 'failed') return false;
  return needsBordereau(s);
};
// ── L'ÉTIQUETTE D'UNE VENTE / D'UN ACHAT, UNE RÈGLE (§11) ─────────────────
// Sortie des composants le 16 octobre : la recherche globale (dans la coque)
// affichait le statut BRUT de Vinted pendant que les cartes disaient « À
// expédier ». Les deux lisent maintenant ces fonctions.
function etapeVente(o, { poste = () => false, expediee = null } = {}) {
  const s = o.status || ''; const tus = tusDe(o);
  // « Commande non réclamée - Retournée à l'expéditeur » n'est PAS un
  // remboursement établi (le mot « expéditeur » faisait conclure « expédiée
  // puis remboursée ») : la paire revient, Vinted rembourse souvent tout seul.
  if (/non\s+r[ée]clam/i.test(s)) return { label: 'Retournée', color: C.warn, step: 0, aide: "L'acheteur n'a pas retiré le colis : il te revient. Vérifie qu'il arrive bien — Vinted règle souvent le remboursement tout seul." };
  if (/retour\s+initi|retour\s+en\s+cours|retour\s+demand/i.test(s)) return { label: 'Retour en cours', color: C.warn, step: 0, aide: "L'acheteur a ouvert un retour : l'article doit te revenir avant le remboursement." };
  // `expediee` inconnu (la recherche n'a ni les bordereaux ni les emails) : le
  // texte de Vinted tranche — « Remboursement » ou non. Jamais deviné au-delà.
  // La transaction le dit annulée alors que la liste ne l'a pas encore vu
  // (« Bordereau envoyé au vendeur ») : c'est une vente annulée (17 oct.).
  const annuleeTxn = o.transaction_id != null && txnAnnuleeAvantEnvoi(o.transaction_id);
  if (annuleeTxn) return { label: 'Annulée', color: C.danger, step: 0, aide: "Commande annulée avant l'envoi — l'article n'est jamais parti. Son bordereau ne sert plus." };
  // Litige : la liste montre le statut du colis de RETOUR (« déposé en point
  // relais ») — la transaction dit ce qui se passe vraiment (17 oct.).
  const et = o.transaction_id != null ? etatTxn(o.transaction_id) : null;
  if (et && et.s === 440) return { label: 'Retour en cours', color: C.warn, step: 0, aide: "L'acheteur a ouvert un retour (litige) : rien à expédier. L'article doit te revenir — marque-le reçu sur Vinted quand il arrive." };
  if (et && et.s === 430) return { label: 'Suspendue', color: C.warn, step: 0, aide: "Vinted vérifie cette transaction (litige ou contrôle) : rien à expédier tant que ce n'est pas réglé." };
  if (classifyOrderStatus(o.status) === 'cancelled') return (expediee ? expediee(o) : /rembours/i.test(s))
    ? { label: 'Remboursée', color: C.danger, step: 0, aide: "Cet article a bien été EXPÉDIÉ, puis remboursé à l'acheteur — l'article et l'argent sont partis. Ce n'est pas une commande annulée avant l'envoi." }
    : { label: 'Annulée', color: C.danger, step: 0, aide: "Commande annulée avant l'envoi — l'article n'est jamais parti." };
  if (/finalis/i.test(s) || tus === 'completed') return { label: 'Vendue', color: INV_STATUS.online.color, step: 4 };
  // ⚠️ COCHÉ « POSTÉ » À LA MAIN (`isShipDone`) : le colis a quitté
  // « À expédier » partout (Colis, Ma journée, la cloche, le filtre) et le
  // filtre « En transit » le montre — mais son étiquette disait encore
  // « À expédier », sous l'intitulé « En transit » (vu au banc
  // `statuts-colis.cjs`, 4 octobre). Vinted le confirmera au premier scan.
  if (aExpedier(o)) return poste(o)
    ? { label: 'Posté', color: C.blue || C.accent, step: 2, aide: "Tu l'as marqué posté : Vinted confirmera l'envoi au premier passage chez le transporteur." }
    : { label: 'À expédier', color: C.warn, step: 1 };
  if (isAtRelayStatus(s)) return { label: 'Au relais', color: C.blue || C.accent, step: 3 };
  if (/\blivr[ée]|remis\b|r[ée]ceptionn/i.test(s)) return { label: 'Livrée', color: C.blue || C.accent, step: 3 };
  if (/transit|achemin|exp[ée]di[ée]|en\s+route/i.test(s) || tus === 'waiting') return { label: 'En transit', color: C.blue || C.accent, step: 2 };
  return { label: 'En cours', color: C.muted, step: 1 };
}
function phaseAchat(status) {
  const s = status || '';
  if (/annul|rembours|refus|litige/i.test(s)) return 'cancelled';
  // « La livraison n'a pas encore eu lieu... », « en attente de... »,
  // « Paiement validé » : la commande est EN COURS, pas reçue.
  if (/pas encore|en attente|suspendu|paiement valid/i.test(s)) return 'pending';
  // livr[ée] (et pas « livraison ») : « Commande livrée » oui, « la
  // livraison n'a pas eu lieu » non.
  if (/finalis|livr[ée]|termin|re[çc]u|complet|arriv/i.test(s)) return 'completed';
  return 'pending';
}
function etapeAchat(o, tk) {
  const s = o.status || '';
  // ⚠️ « Retour initié » sur un ACHAT = litige, tu dois RENVOYER la paire.
  //    Testé AVANT « annulé/remboursé » : ce n'est pas une commande morte,
  //    c'est une action à faire (générer le bordereau de retour sur Vinted).
  //    Motif précis (comme venteStage) pour ne pas attraper « Retournée à
  //    l'expéditeur », qui est autre chose.
  if (ACHAT_A_RENVOYER.test(s)) return { label: 'À renvoyer', step: 1, color: C.warn, retour: true };
  if (/annul|rembours|refus/i.test(s)) return { label: 'Annulé', step: 0, color: C.danger };
  if (/finalis/i.test(s) || tusDe(o) === 'completed') return { label: 'Reçu', step: 4, color: INV_STATUS.online.color };
  if (isAtRelayStatus(s) || (tk && tk.status === 'available')) return { label: 'À retirer', step: 3, color: C.warn };
  if (/\blivr[ée]|remis\b|r[ée]ceptionn/i.test(s) || phaseAchat(s) === 'completed') return { label: 'Reçu', step: 4, color: INV_STATUS.online.color };
  if (/exp[eé]di|transit|achemin|en route|envoy/i.test(s)) return { label: 'En transit', step: 2, color: C.blue || C.accent };
  if (/pay|valid|pr[ée]par|attente|confirm/i.test(s)) return { label: 'Payé', step: 1, color: C.muted };
  return { label: s ? (s.length > 26 ? s.slice(0, 26) + '…' : s) : 'En cours', step: 1, color: C.muted };
}
// ── LA DATE LIMITE D'ENVOI : api/_lib/limite-envoi.js (22 octobre) ─────────
// `limiteExpedition(o, b)` et `DELAI_EXPEDITION_J` (7 jours mesurés, jamais
// moins sur 202 ventes reliées à leur bordereau) vivent dans ce module, importé
// ici ET par le serveur (rappels du matin et du soir, widget) : une règle (§11).
// ⚠️ L'HEURE COMPTE : mesuré le 22 octobre, 204 bordereaux sur 205 donnent une
// heure limite (90 à « 10 h 00 ») et ce calcul la jetait (fin de journée,
// 23:59:59) — « avant demain 10 h » s'affichait « demain ». Une limite dépassée
// le jour même (« avant 10 h », il est 11 h) vaut « en retard ». Heure
// illisible ⇒ le jour seul, comme avant. L'heure est celle de PARIS.

// ── « COCHÉ POSTÉ » MAIS JAMAIS VU PARTIR (6 octobre) ───────────────────────
// Cocher « Colis fait » (`vinted_ship_done`) sort la vente de « à envoyer »
// PARTOUT — c'est voulu, il vient de la déposer. Mais rien ne revenait vérifier
// que Vinted l'avait bien vue partir. MESURÉ le 6 octobre sur sa base : deux
// ventes (65 € et 75 €) cochées « posté » il y a 159 h et 92 h, que Vinted
// disait TOUJOURS « Bordereau envoyé au vendeur » dans une capture faite APRÈS
// la coche — aucune alerte nulle part. Un colis oublié sur l'étagère, c'est une
// vente que Vinted annule à la date limite.
// RÈGLE (une seule, consommée par Colis et Ma journée) — tout doit être SU :
//   · la date de la coche (un horodatage ; autre chose ⇒ pas su, on se tait) ;
//   · Vinted dit encore « à expédier » (`aExpedier`, le champ machine d'abord),
//     et aucun email du transporteur ne l'a vu passer ;
//   · ce statut a été lu APRÈS la coche (`captureAt` > coche) — un statut lu
//     avant ne prouve rien : deux autres ventes cochées le 29 septembre ne sont
//     connues que par une capture du 20, on ne les accuse pas ;
//   · et la date limite est dépassée, OU la coche a plus de 48 h (le temps
//     qu'un transporteur scanne un dépôt du soir ou du week-end).
const POSTE_SANS_DEPART_H = 48;
const posteSansDepart = ({ o, cocheLe, captureAt, joursLimite, vuParTransporteur, maintenant = Date.now() }) => {
  if (!o) return null;
  const t = Number(cocheLe);
  if (!isFinite(t) || t < 1e12) return null;            // pas su QUAND il l'a coché
  if (vuParTransporteur) return null;                   // le transporteur l'a vu passer
  if (!aExpedier(o)) return null;                       // Vinted l'a vu partir (ou n'attend plus d'envoi)
  const cap = Number(captureAt);
  if (!isFinite(cap) || cap <= t) return null;          // statut lu AVANT la coche : pas su
  const heures = (maintenant - t) / 3600000;
  const limiteDepassee = joursLimite != null && joursLimite < 0;
  if (heures < POSTE_SANS_DEPART_H && !limiteDepassee) return null;
  return { heures: Math.floor(heures), limiteDepassee, joursLimite: joursLimite == null ? null : joursLimite };
};

// Recupere une page d'achats ou de ventes pour un compte (endpoint reel
// trouve via "Copy as fetch" : www.vinted.fr/api/v2/my_orders).
// type: 'purchased' | 'sold' ; statusFilter: 'completed' | 'pending' | 'cancelled' | 'all'
const fetchVintedOrders = async (account, type, page = 1, statusFilter = 'completed', opts = {}) => {
  const applyStatus = (items) => {
    if (statusFilter === 'pending') return items.filter(it => classifyOrderStatus(it.status) === 'pending');
    if (statusFilter === 'cancelled') return items.filter(it => classifyOrderStatus(it.status) === 'cancelled');
    if (statusFilter === 'completed') return items.filter(it => classifyOrderStatus(it.status) === 'completed');
    return items;
  };
  // 1) Données moissonnées par l'extension (aucun appel Vinted). On sépare
  //    achats/ventes par le type d'URL capté ; repli sur l'ancienne clé générique.
  //    opts.force = on saute la moisson (bouton "Synchroniser") pour le dernier état.
  if (page === 1 && !opts.force) {
    // ⚠️ PAS de repli sur la ligne générique `harvest_{uid}_orders` : elle est
    // écrite quand Vinted charge /my_orders SANS préciser ?type=, donc elle
    // contient un MÉLANGE ventes + achats. S'en servir affichait des achats
    // dans les ventes (et l'inverse). On n'accepte que les lignes explicitement
    // « sold » ou « purchased ». Mesuré : la ligne générique est vide de toute
    // façon, ce repli ne rapportait rien et ne pouvait que tromper.
    const h = await fetchHarvestOrders(account.vinted_user_id, type);
    // Lecture de NOTRE base en échec : c'est un échec, pas un compte jamais
    // moissonné — on ne part surtout pas interroger Vinted pour autant.
    if (h === undefined) return { ok: false, error: 'lecture', items: [], pagination: null, source: 'harvest-ko' };
    // ⚠️ Une moisson VIDE n'est pas une réponse. Une liste vide veut dire « la
    // page n'a pas encore été ouverte / la session a expiré », pas « aucune
    // vente ». En la prenant pour argent comptant, l'onglet Ventes affichait
    // zéro vente alors qu'il y en avait — on continue vers le proxy.
    if (h && Array.isArray(h.my_orders)) {
      // Moisson NON vide : c'est la réponse.
      if (h.my_orders.length > 0) {
        return { ok: true, items: applyStatus(h.my_orders), pagination: h.pagination || null, source: 'harvest' };
      }
      // Moisson PRÉSENTE mais vide. On ne va PAS interroger Vinted pour autant :
      // avec 8 comptes, ça faisait ~20 appels depuis l'IP du serveur à chaque
      // ouverture — précisément le motif « multi-comptes piloté par un robot »
      // que Vinted détecte. Les ventes sont de toute façon reconstituées depuis
      // les emails (plus complètes ici), et les achats aussi. Le bouton
      // « Synchroniser » (opts.force) reste là pour aller chercher le direct.
      // ⚠️ Ligne ABSENTE (h == null) = compte jamais moissonné : là, on tente
      // le proxy, sinon un compte tout neuf n'afficherait jamais rien.
      return { ok: true, items: [], pagination: null, source: 'harvest-vide' };
    }
  }
  // Mode "moisson seulement" : on n'interroge PAS Vinted, on renvoie du vide si
  // la page n'a pas encore été ouverte dans le navigateur.
  if (opts.harvestOnly) return { ok: true, items: [], pagination: null, source: 'harvest' };
  // `moissonSeule` (revue 5.165) : une relecture déclenchée par un SIGNAL de
  // l'extension. Pas de ligne ⇒ « rien de neuf à dire » (l'appelant garde ce
  // qu'il montrait) — jamais le relais serveur, jamais un faux « 0 ».
  if (opts.moissonSeule) return { ok: false, error: 'moisson-absente', items: [], pagination: null, source: 'moisson-absente' };
  // 2) Repli : proxy — on récupère TOUTES les pages. ⚠️ Avant, on ne prenait
  //    que la 1re page de 20 commandes/compte → CA, « en attente » et coûts
  //    d'achat étaient largement sous-comptés (ex. 71 ventes lues comme 20).
  //    per_page=100 suffit en 1 appel pour la plupart des comptes ; on boucle
  //    par sécurité pour les gros comptes (plafond pour rester raisonnable).
  const perPage = 100; const maxPages = 12;
  let all = []; let anyOk = false;
  for (let pg = 1; pg <= maxPages; pg++) {
    const endpoint = statusFilter === 'completed'
      ? `/api/v2/my_orders?type=${type}&status=completed&per_page=${perPage}&page=${pg}`
      : `/api/v2/my_orders?type=${type}&per_page=${perPage}&page=${pg}`;
    const res = await vintedApiCall(account, endpoint);
    if (!res.ok) { if (pg === 1) return { ok: false, error: res.status || res.error, items: [], pagination: null }; break; }
    anyOk = true;
    const batch = res.data?.my_orders || [];
    all = all.concat(batch);
    const totalPages = res.data?.pagination?.total_pages;
    if (batch.length < perPage || (totalPages && pg >= totalPages)) break;
  }
  return { ok: anyOk, items: applyStatus(all), pagination: null };
};

// Recupere la liste des conversations (boite de reception).
// Endpoint reel confirme : GET /api/v2/inbox -> { conversations: [...] }.
// Chaque conversation contient : id, description (titre de l'article),
// unread, updated_at, opposite_user {id, login, photo}, item_photos.
// (Les anciennes tentatives /api/v2/conversations et /transaction_messages
// renvoyaient 404 ; /api/v2/inbox est le bon chemin.)
const fetchVintedConversations = async (account, page = 1, opts = {}) => {
  // 1) Priorité aux données moissonnées par l'extension (aucun appel Vinted).
  //    opts.force = on saute la moisson (bouton "Synchroniser") pour le dernier état.
  if (page === 1 && !opts.force) {
    const h = await fetchHarvest(account.vinted_user_id, 'inbox');
    // Une moisson VIDE n'est pas une réponse (cf. fetchVintedOrders) : la page
    // n'a pas encore été ouverte ou la session a expiré. On va voir plus loin.
    if (h && Array.isArray(h.conversations)) {
      if (h.conversations.length > 0) {
        return { ok: true, items: h.conversations, pagination: h.pagination || null, raw: null, source: 'harvest' };
      }
      // Boîte de réception moissonnée mais vide : on n'interroge PAS Vinted.
      // Mesuré : ça déclenchait 16 appels au démarrage (8 comptes × 2 domaines)
      // depuis l'IP du serveur, sans que l'écran Messages soit même ouvert —
      // le signal exact que Vinted lit comme du multi-comptes automatisé.
      return { ok: true, items: [], pagination: null, raw: null, source: 'harvest-vide' };
    }
  }
  if(opts.force && extSait('messagerie')==='ok') {
    const r=await vmrExec({uid:account.vinted_user_id,method:'GET',endpoint:`/api/v2/inbox?page=${page}&per_page=20`});
    if(r?.ok && Array.isArray(r.data?.conversations)) {
      const h=await fetchHarvest(account.vinted_user_id,'inbox');
      const tous=new Map((h?.conversations || []).map(c=>[String(c.id),c]));
      r.data.conversations.forEach(c=>tous.set(String(c.id),c));
      return {ok:true,items:[...tous.values()],pagination:r.data.pagination || null,source:'extension'};
    }
    const h=await fetchHarvest(account.vinted_user_id,'inbox');
    if(Array.isArray(h?.conversations))return {ok:true,items:h.conversations,source:'harvest',stale:true};
    return {ok:false,error:r?.error || 'lecture-indisponible',items:[]};
  }
  // Mode "moisson seulement" : aucun appel Vinted.
  if (opts.harvestOnly) return { ok: true, items: [], pagination: null, raw: null, source: 'harvest' };
  if (opts.moissonSeule) return { ok: false, error: 'moisson-absente', items: [], pagination: null, raw: null, source: 'moisson-absente' };
  // 2) Repli : proxy (si l'inbox n'a pas encore été ouverte dans le navigateur).
  const res = await vintedApiCall(account, `/api/v2/inbox?page=${page}&per_page=20`);
  if (!res.ok) return { ok: false, error: res.status || res.error, items: [], pagination: null, raw: res };
  const items = res.data?.conversations || [];
  return {
    ok: true,
    items,
    pagination: res.data?.pagination || null,
    raw: res,
  };
};

// Recupere le detail d'une conversation (fil de messages).
// Endpoint reel confirme : GET /api/v2/conversations/{id} -> { conversation }.
// conversation.messages est une liste d'entites { entity_type, entity }.
// entity_type = 'message' pour un vrai message (entity.body + entity.user_id) ;
// d'autres types existent (offer_request_message, status_message,
// action_message) qu'on affiche comme evenements. Pour distinguer "moi" de
// "l'acheteur" on compare entity.user_id a opposite_user.id (fiable meme si
// l'id vendeur differe du vinted_user_id du compte).
const fetchVintedConversationDetail = async (account, conversationId, {force=false}={}) => {
  // 1) Données moissonnées (si tu as déjà ouvert ce fil sur vinted.fr).
  const h = await fetchHarvestConversation(account.vinted_user_id, conversationId);
  if (!force && h && h.conversation) return { ok:true,conversation:h.conversation,source:'harvest' };
  // 2) L'extension, depuis TON navigateur (5.135) : une lecture, au nom du
  //    compte connecté dans Chrome. Refusée (autre compte, absente) ⇒ repli.
  if (extSait('messagerie') === 'ok') {
    const r = await vmrExec({ uid: account.vinted_user_id, method: 'GET', endpoint: `/api/v2/conversations/${conversationId}` });
    if (r && r.ok && r.data && r.data.conversation) { const c = fusionnerConversation(h?.conversation, r.data.conversation); if (c) return { ok: true, conversation: c, source: 'extension' }; }
  }
  if(h?.conversation)return {ok:true,conversation:h.conversation,source:'harvest'};
  // 3) Repli : proxy.
  const res = await vintedApiCall(account, `/api/v2/conversations/${conversationId}`);
  if (!res.ok) return { ok: false, error: res.status || res.error, conversation: null };
  const c = fusionnerConversation(h?.conversation, res.data?.conversation);
  return c ? { ok: true, conversation: c } : { ok:false,conversation:null,error:'Cette conversation n’a pas pu être lue.' };
};

// Aplati les entites d'une conversation en messages affichables et tries.
// Extrait TOUT le texte lisible d'une entité d'évènement système : titre,
// sous-titre, corps, actions... ET surtout tout champ qui ressemble à un CODE
// (retrait en point relais, PIN, suivi, référence). Vinted range parfois le
// « code de retrait » dans un champ imbriqué : on scanne défensivement pour ne
// rien cacher (« voir tout dans la conv »).
const extractEventText = (e, entity_type) => {
  const parts = [];
  ['title','subtitle','body','text','header','description'].forEach(k => { if (typeof e[k] === 'string' && e[k].trim()) parts.push(e[k].trim()); });
  const seen = new Set(parts);
  const scan = (obj, depth = 0) => {
    if (!obj || typeof obj !== 'object' || depth > 6) return;
    for (const k in obj) {
      const v = obj[k];
      if ((typeof v === 'string' && v.trim()) || (typeof v==='number' && Number.isFinite(v))) {
        const texte=String(v).trim();
        // Champs qui portent typiquement un code / numéro de suivi / retrait.
        if (/code|pin|pickup|retrait|tracking|suivi|reference|référence|numero|numéro|colis|shipment|drop/i.test(k) && !seen.has(texte)) {
          const label=/pickup|retrait|pin/i.test(k)?'Code de retrait':/tracking|suivi/i.test(k)?'Suivi':/reference|référence/i.test(k)?'Référence':k;
          seen.add(texte); parts.push(`${label}: ${texte}`);
        }
      } else if (v && typeof v === 'object') scan(v, depth + 1);
    }
  };
  scan(e);
  return parts.length ? [...new Set(parts)].join(' · ') : entity_type;
};

// Récupère tous les LIENS d'une entité (le bordereau/étiquette d'expédition est
// souvent un lien dans la conversation). On scanne en profondeur, on repère les
// liens de type bordereau/étiquette/suivi pour les mettre en avant.
const URL_RE = /(https?:\/\/[^\s"'<>]+)/gi;
const extractLinks = (e) => {
  const found = []; const seen = new Set();
  const push = (url, ctx) => {
    url = url.replace(/[.,)]+$/, '');
    if (!/^https?:\/\//i.test(url) || seen.has(url)) return;
    seen.add(url);
    const hay = (url + ' ' + (ctx||'')).toLowerCase();
    const isBordereau = /label|bordereau|shipping|shipment|étiquette|etiquette|parcel|colis|waybill|expedition|expédition|\.pdf/.test(hay);
    found.push({ url, bordereau: isBordereau });
  };
  const scan = (obj, key = '', depth = 0) => {
    if (obj == null || depth > 4) return;
    if (typeof obj === 'string') {
      let m; URL_RE.lastIndex = 0;
      while ((m = URL_RE.exec(obj))) push(m[1], key);
      // champ dédié dont la clé évoque un lien direct (url/link/href)
      if (/url|link|href|download/i.test(key) && /^https?:\/\//i.test(obj)) push(obj, key);
      return;
    }
    if (typeof obj === 'object') for (const k in obj) scan(obj[k], k, depth + 1);
  };
  scan(e);
  return found;
};

const normalizeConversationMessages = (conversation) => {
  if (!conversation || !Array.isArray(conversation.messages)) return [];
  const oppId = conversation.opposite_user?.id;
  const messages=conversation.messages.map((m) => {
    const e = m.entity || {};
    const brut=m.created_at_ts ?? e.created_at_ts ?? m.created_at ?? e.created_at;
    const nombre=Number(brut);const date=brut==null || brut===''?null:Number.isFinite(nombre)?(nombre<1e12?nombre*1000:nombre):(Date.parse(brut)||null);
    const ts=date!=null && Number.isFinite(new Date(date).getTime())?date:null;
    const links = extractLinks(e);
    if (m.entity_type === 'message') {
      return { kind: 'message', mine:e.user_id!=null && oppId!=null && String(e.user_id)!==String(oppId), body: e.body || '', photos:Array.isArray(e.photos)?e.photos:[], ts, links };
    }
    if(m.entity_type==='offer_request_message'){
      const brutPrix=e.price&&typeof e.price==='object'?e.price.amount:e.price;
      const montant=typeof brutPrix==='number'?brutPrix:typeof brutPrix==='string'&&/^\d+(?:[,.]\d{1,2})?$/.test(brutPrix.trim())?Number(brutPrix.replace(',','.')):null;
      if(Number.isFinite(montant)&&montant>0){
        const deviseBrute=e.price?.currency_code||e.price?.currency;
        const devise=typeof deviseBrute==='string'&&/^[A-Z]{3}$/.test(deviseBrute)?deviseBrute:null;
        const sens=e.user_id!=null&&oppId!=null?(String(e.user_id)===String(oppId)?'recue':'envoyee'):'inconnu';
        const statut=etatOffreVinted(e).libelle;
        return {kind:'offer',body:'',offre:{montant,devise,sens,statut},ts,links};
      }
    }
    // Évènements système (offre, statut, expédition, retrait…) : on montre TOUT,
    // codes de retrait compris.
    return { kind: 'event', body: extractEventText(e, m.entity_type), ts, links };
  });
  return messages.every(m=>m.ts!=null)?messages.sort((a,b)=>a.ts-b.ts):messages;
};
