  close:  <><path d="m6 6 12 12M18 6 6 18"/></>,
  chevron: <><path d="m9.5 6 6 6-6 6"/></>,
  pencil: <><path d="M4 20.2h4l10-10a2.8 2.8 0 0 0-4-4l-10 10v4Z"/><path d="m14.5 5.5 4 4"/></>,
