const dateCourteFr = (iso) => { const d = new Date(iso); return isNaN(d) ? '' : d.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' }); };
// Ce que dit un compte muet, sur sa ligne : la PREUVE (ses ventes sans email),
// jamais une supposition sur la cause.
const phraseCompteMuet = (l) => l.jamais
  ? `aucun email de Vinted n’est jamais arrivé — ${l.nSansEmail} vente${l.nSansEmail > 1 ? 's' : ''} depuis le ${dateCourteFr(l.premiereSansEmail)}, aucune n’a eu son email`
  : `plus aucun email depuis le ${dateCourteFr(l.depuis)} — ${l.nSansEmail} vente${l.nSansEmail > 1 ? 's' : ''} depuis, sans leur email`;
// Un compte qui a vendu SANS email, mais pas assez pour conclure : sa phrase à
// lui, tirée de la donnée (jamais « n'a pas encore vendu » — revue du 11 oct.).
const phraseCompteSurveille = (l) => {
  const s = (k) => (k > 1 ? 's' : '');
  if (l.raisonSurveiller === 'aucunDebut') return 'VRM n’a encore reçu aucun email — rien à conclure';
  if (l.raisonSurveiller === 'peu') return `${l.nSansEmail} vente${s(l.nSansEmail)} sans email depuis le ${dateCourteFr(l.premiereSansEmail)}${l.nRecentes ? ` (+ ${l.nRecentes} récente${s(l.nRecentes)})` : ''} — pas encore de quoi conclure`;
  return `${l.nRecentes} vente${s(l.nRecentes)} de moins de 3 jours — ${l.nRecentes > 1 ? 'leur' : 'son'} email peut encore arriver`;
};
// Le bloc : qui, depuis quand, ce que ça coûte (une fois), et LE geste (une fois).
// ⚠️ « Masquer mon adresse » n'est PAS la cause prouvée (deux comptes à adresse
//    Apple recevaient très bien leurs emails, relecture du 11 octobre) : c'est
//    UNE vérification de plus, dite seulement pour les comptes concernés. La
//    première vérification est celle des notifications email de Vinted.
function BlocComptesMuets({ muets }) {
  if (!muets || !muets.length) return null;
  const n = muets.length;
  const apple = muets.filter((l) => l.relaisApple);
  const tousApple = apple.length === n;
  return (
    <div data-comptes-muets={n} style={{border:`1px solid ${C.warn}`,borderLeft:`3px solid ${C.warn}`,background:`${C.warn}10`,borderRadius:8,padding:'9px 11px'}}>
      <div style={{fontSize:12.5,fontWeight:700,color:C.text}}>
        {n} compte{n>1?'s':''} Vinted n’envoie{n>1?'nt':''} aucun email à VRM
      </div>
      <div style={{display:'flex',flexDirection:'column',gap:3,marginTop:5}}>
        {muets.map((l) => (
          <div key={l.uid} data-compte-muet={l.login} style={{fontSize:11.5,color:C.muted,lineHeight:1.45}}>
            <b style={{color:C.text}}>{l.login}</b> — {phraseCompteMuet(l)}{l.relaisApple && !tousApple ? ' (adresse « Masquer mon adresse » d’Apple)' : ''}.
          </div>
        ))}
      </div>
      {/* ⚠️ REVUE DU 11 OCTOBRE : ce qui est PROUVÉ, pas plus. « Leurs codes de
          retrait n'arrivent pas » n'était pas prouvé (ils viennent des
          transporteurs, côté achats), et la phrase parlait au pluriel pour un
          seul compte.
          ⚠️ (22 oct.) « Pas de rappel du matin pour leurs colis » est devenu
          FAUX : le rappel du matin compte maintenant toutes les ventes à
          expédier (la liste du soir). Ce qui reste vrai et prouvé : sans
          l'email du bordereau, la date limite de leurs colis est ESTIMÉE (vente
          + 7 jours, sans l'heure — 90 bordereaux sur 205 disent « avant 10 h »). */}
      <div style={{fontSize:11.5,color:C.muted,marginTop:6,lineHeight:1.45}} data-effet-muets>
        {n>1?'Leurs':'Ses'} ventes s’affichent bien (l’extension les capte), mais {n>1?'leurs':'ses'} bordereaux n’arrivent pas par email&nbsp;: <b style={{color:C.text}}>la date limite de {n>1?'leurs':'ses'} colis est estimée (vente + 7 jours, sans l’heure)</b>, et ton téléphone ne sonne ni pour {n>1?'leurs':'ses'} ventes ni pour {n>1?'leurs':'ses'} messages.
      </div>
      <div style={{fontSize:11.5,color:C.text,marginTop:6,lineHeight:1.5}} data-geste-muets>
        <b>Pour {n>1?'chacun':'ce compte'}&nbsp;:</b> 1. sur Vinted, connecté sur {n>1?'ce compte':muets[0].login}&nbsp;: <b>Paramètres → Notifications</b>, active les e-mails (messages, offres, ventes).
        {' '}2. {tousApple
          ? <>{n>1?'Leur':'Son'} adresse est une adresse « Masquer mon adresse » d’Apple&nbsp;: sur l’iPhone, <b>Réglages → ton nom → Connexion et sécurité → Se connecter avec Apple → Vinted → Transférer à</b>, choisis la boîte reliée à VRM.</>
          : <>Vérifie que sa boîte fait suivre les emails de Vinted vers celle reliée à VRM{apple.length ? <> — pour {apple.map((l) => l.login).join(', ')} (adresse « Masquer mon adresse » d’Apple)&nbsp;: sur l’iPhone, <b>Réglages → ton nom → Connexion et sécurité → Se connecter avec Apple → Vinted → Transférer à</b></> : null}.</>}
      </div>
    </div>
  );
}
function MuetsCompact({ muets, detail }) {
  const [ouvert, setOuvert] = useState(false);
  const n = muets.length;
  return (
    <details data-muets-compact={n} style={{marginBottom:10}} onToggle={(e) => setOuvert(e.currentTarget.open)}>
      <summary style={{cursor:'pointer',listStyle:'none',display:'flex',alignItems:'center',gap:7,fontSize:12,fontWeight:600,color:C.text,padding:'6px 10px',border:`1px solid ${C.warn}`,borderLeft:`3px solid ${C.warn}`,background:`${C.warn}10`,borderRadius:8}}>
        <span aria-hidden="true" style={{color:C.warn,display:'flex'}}><Icon name="alert" size={14}/></span>
        <span style={{flex:1,minWidth:0}}>{ouvert ? 'Masquer' : <>{n} compte{n>1?'s':''} n’envoie{n>1?'nt':''} aucun email à VRM — voir {n>1?'lesquels':'lequel'} et le geste</>}</span>
        <span aria-hidden="true" style={{color:C.muted}}>{ouvert ? '▴' : '▾'}</span>
      </summary>
      <div style={{marginTop:6}}><BlocComptesMuets muets={muets}/></div>
      <details style={{marginTop:6}}>
        <summary style={{cursor:'pointer',fontSize:11.5,color:C.muted}}>Le détail : transporteurs et comptes</summary>
        <div style={{marginTop:8,border:`1px solid ${C.border}`,background:C.card,borderRadius:10,padding:'10px 12px'}}>{detail}</div>
      </details>
    </details>
  );
}
function ReceptionEmails({ tracking, comptes, colisParTransporteur }) {
  const [incompris, setIncompris] = useState(null);
  const etatComptes = useEtatEmailsComptes(comptes);
  useEffect(() => {
    let mort = false;
    fetchEmailsIncompris().then(r => { if (!mort) setIncompris(r); });
    return () => { mort = true; };
  }, []);
  const lignes = useMemo(() => {
    const m = {};
    for (const t of (tracking || [])) {
      const k = carrierKey(t && t.carrier) || 'autre';
      const d = t && t.receivedAt ? Date.parse(t.receivedAt) : NaN;
      if (isNaN(d)) continue;
      if (!m[k] || d > m[k].ts) m[k] = { ts: d, n: (m[k] ? m[k].n : 0) + 1 };
      else m[k].n += 1;
    }
    for (const k of ['chronopost', 'mondialrelay', 'vinted']) if (!m[k]) m[k] = { ts: 0, n: 0 };
    return Object.entries(m).sort((a, b) => b[1].ts - a[1].ts);
  }, [tracking]);
  const age = (ts) => {
    if (!ts) return null;
    const h = (Date.now() - ts) / 3600000;
    return h < 1 ? "à l'instant" : h < 24 ? `il y a ${Math.round(h)} h` : `il y a ${Math.round(h / 24)} j`;
  };
  // ⚠️ « Non compris » doit vouloir dire quelque chose. Les familles reconnues
  // sans action (évaluations, newsletters, « commande mise à jour », les emails
  // que Julien envoie lui-même à Vinted) sont comptées à part : sinon le
  // compteur crie au loup et on cesse de le regarder.
  const vraimentInconnus = useMemo(() => (incompris || []).filter(e => !String(e.famille || '').trim() && !familleEmail(e.subject, e.from)), [incompris]);
  const nInc = vraimentInconnus.length;
  const nConnus = (incompris ? incompris.length : 0) - nInc;
  // Un compte MUET, sur preuve : des ventes captées qui n'ont eu aucun email
  // depuis son dernier signe de vie (`etatEmailsComptes`). « Aucun email » seul
  // ne prouve rien — un compte qui n'a rien vendu n'avait rien à recevoir.
  const muets = etatComptes.muets;
  // ⚠️⚠️ « ON LES ATTEND » N'EST PAS VRAI LE PREMIER JOUR. Vu au rendu le
  //    16 septembre sur une installation neuve : « Réception des emails ·
  //    3 transporteurs silencieux », en ambre, avec trois « aucun email reçu »
  //    en rouge — à quelqu'un qui vient de créer son compte et n'a encore rien
  //    acheté. Rien ne se tait : rien n'a commencé. Une fausse alerte est ce
  //    qui fait cesser de lire les vraies (leçon du panneau de sécurité et du
  //    compte exclu). Trois états, jamais deux : jamais rien reçu · certains
  //    muets · tout arrive.
  // ⚠️ §4.6 : `detail` est un élément JSX construit IMMÉDIATEMENT, et il lit
  //    cette valeur — posée plus bas, l'écran Achats mourait sur « Cannot
  //    access before initialization ». C'est le RENDU qui l'a vu, pas le build.
  const aucunEmailDeSuivi = lignes.every(([, v]) => !v.ts);
  const ligne = { display: 'flex', alignItems: 'center', gap: 8, fontSize: 12 };
  // Le DÉTAIL (transporteurs + comptes, un par ligne) : c'est la preuve, pas
  // l'alerte. Il vit derrière un dépliant dans les deux cas, pour que l'écran
  // Achats commence par les colis et non par un tableau de diagnostic.
  const detail = (
    <>
      <div style={{display:'flex',flexDirection:'column',gap:5}}>
        {lignes.map(([k, v]) => {
          const nColis = (colisParTransporteur && colisParTransporteur[k]) || 0;
          return (
            <div key={k} style={ligne}>
              <CarrierBadge carrier={k} size={18}/>
              <div style={{flex:1,minWidth:0,color:C.text,whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>
                {carrierName(k)}
                {nColis>0 && <b style={{color:C.accent}}> · {nColis} colis à retirer</b>}
              </div>
              <div style={{color:v.ts?(Date.now()-v.ts<3*86400000?(C.ok||C.accent):C.warn):(aucunEmailDeSuivi?C.muted:C.danger),fontWeight:600,flexShrink:0,textAlign:'right'}}>
                {v.ts ? `${v.n} email${v.n>1?'s':''} · ${age(v.ts)}` : aucunEmailDeSuivi ? 'rien encore' : 'aucun email reçu'}
              </div>
            </div>
          );
        })}
      </div>
      {comptes && comptes.length > 0 && (
        <div style={{marginTop:9,paddingTop:8,borderTop:`1px solid ${C.border}`}}>
          <div style={{fontSize:11.5,fontWeight:600,color:C.text,marginBottom:5}}>Tes comptes Vinted et leurs emails</div>
          {etatComptes.etat === 'encours' && <div style={{fontSize:11,color:C.muted}}>lecture en cours…</div>}
          {etatComptes.etat === 'pasSu' && <div style={{fontSize:11,color:C.muted}}>Je n’ai pas pu lire les emails reçus : je ne dis rien des comptes plutôt que d’en accuser un à tort. Rouvre cet écran dans un moment.</div>}
          {etatComptes.etat === 'lu' && (
            <div style={{display:'flex',flexDirection:'column',gap:4}}>
              {/* ⚠️ §7 (revue du 11 oct.) : un compte déjà nommé dans le bloc
                  au-dessus n'est pas redit ici. */}
              {etatComptes.lignes.filter(l => !(muets.length && l.statut === 'muet')).map(l => {
                const ts = l.last ? Date.parse(l.last) : NaN;
                // ⚠️ Plus de rouge (§7 : le rouge est pour deux paires sous un
                //    même numéro). Ambre seulement pour un compte PROUVÉ muet.
                const coul = l.statut === 'muet' ? C.warn
                  : l.statut === 'recoit' ? (!isNaN(ts) && Date.now()-ts<7*86400000 ? (C.ok||C.accent) : C.muted)
                  : C.muted;
                const txt = l.statut === 'muet' ? (l.jamais ? 'aucun email, jamais' : `plus rien depuis le ${dateCourteFr(l.depuis)}`)
                  : l.statut === 'recoit' ? `${l.n} email${l.n>1?'s':''}${isNaN(ts)?'':' · '+age(ts)}`
                  : l.statut === 'surveiller' ? phraseCompteSurveille(l)
                  : l.statut === 'exclu' ? 'exclu de l’app — non vérifié'
                  : l.statut === 'calme' ? 'aucun email pour l’instant'
                  : l.statut === 'encours' ? '…' : '—';
                return (
                  <div key={l.uid} data-compte-email={l.login} data-statut={l.statut} style={{...ligne,fontSize:11.5,flexWrap:'wrap'}}>
                    <div style={{flex:'1 1 110px',minWidth:0,color:C.text,whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>{l.login}</div>
                    <div style={{flex:'0 1 auto',minWidth:0,fontWeight:600,color:coul,textAlign:'right'}}>{txt}</div>
                  </div>
                );
              })}
              {muets.length > 0 && (
                <div style={{fontSize:10.5,color:C.muted}}>+ {muets.length} compte{muets.length>1?'s':''} nommé{muets.length>1?'s':''} au-dessus.</div>
              )}
              {/* La phrase vient de la MÊME source que le statut (§5) : « calme »
                  = aucune vente depuis le début de la réception. */}
              {etatComptes.lignes.some(l => l.statut === 'calme') && (
                <div style={{fontSize:10.5,color:C.muted,marginTop:2}} data-note-calme>« Aucun email pour l’instant » n’est pas une panne : {etatComptes.lignes.filter(l => l.statut === 'calme').length > 1 ? 'ces comptes n’ont rien vendu' : 'ce compte n’a rien vendu'}{etatComptes.debut ? ` depuis le ${dateCourteFr(etatComptes.debut)}, premier email reçu par VRM` : ''} — rien n’avait à arriver.</div>
              )}
            </div>
          )}
        </div>
      )}
      {nInc>0 && (
        <div style={{marginTop:9,paddingTop:8,borderTop:`1px solid ${C.border}`}}>
          <div style={{fontSize:11.5,fontWeight:600,color:C.text,marginBottom:4}}>{nInc} email{nInc>1?'s':''} que l'app n'a pas su classer</div>
          {vraimentInconnus.slice(0,4).map(e=>(
            <div key={e.id} style={{fontSize:10.5,color:C.muted,whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>
              {(e.at||'').slice(0,16).replace('T',' ')} · {e.subject || '(sans sujet)'}
            </div>
          ))}
          <div className="vrm-aide" style={{fontSize:10.5,color:C.muted,marginTop:4}}>Ils sont conservés entiers — rien n'est perdu.</div>
        </div>
      )}
      {nInc===0 && nConnus>0 && (
        <div style={{fontSize:10.5,color:C.muted,marginTop:9,paddingTop:8,borderTop:`1px solid ${C.border}`}}>
          {nConnus} email{nConnus>1?'s':''} reconnu{nConnus>1?'s':''} sans action à faire (évaluations, newsletters, mises à jour de commande).
        </div>
      )}
    </>
  );
  const muetsTr = aucunEmailDeSuivi ? 0 : lignes.filter(([, v]) => !v.ts).length;
  const probleme = muets.length > 0 || nInc > 0;
  // ── QUAND QUELQUE CHOSE CLOCHE : on le NOMME, avec le geste à faire.
  //    Un compte muet est le cas grave : ses codes de retrait n'arrivent jamais.
  if (probleme) {
    if (muets.length > 0) {
      // ⚠️ REVUE DU 11 OCTOBRE : déplié d'office, ce bloc faisait 312 px à
      //    390 px (125 avant) et repoussait les colis que personne n'est venu
      //    chercher — de l'argent perdu — sous une information de configuration
      //    qu'on règle une fois. Dans Achats : UNE ligne, qui s'ouvre sur le bloc
      //    complet (Réglages → Notifications le garde en entier).
      // (Ne pas écrire ici le titre exact de ce bloc-là : `audit-retrait` le
      //  trouve par sa première occurrence dans le fichier.)
      return <MuetsCompact muets={muets} detail={detail}/>;
    }
    return (
      <Notice tone="warn" icon="alert"
        value={nInc}
        title={`email${nInc>1?'s':''} reçu${nInc>1?'s':''} que l'app n'a pas su classer`}
        desc="Ils sont conservés entiers, rien n'est perdu — mais aucune action n'en a été tirée."
        detail={detail}/>
    );
  }
  // ⚠️ (revue du 23 oct.) Les e-mails de suivi PAS LUS (lecture ratée ou en
  // cours) ne sont pas « aucun e-mail de suivi reçu » : « pas su » ne vaut pas
  // « rien » (§4.1). L'écran Achats dit la panne une fois, avec « Réessayer ».
  if (!Array.isArray(tracking)) return null;
  // ── QUAND TOUT VA BIEN : une ligne, pas un tableau. Le détail reste à un clic.
  return (
    <details style={{marginBottom:10}}>
      <summary className="vrm-reception-sum" style={{listStyle:'none',cursor:'pointer',display:'flex',alignItems:'center',gap:7,fontSize:11.5,color:C.muted,padding:'2px 0'}}>
        {/* ⚠️ Ni triangle ambre (rien ne cloche), ni coche verte (rien n'est
            confirmé non plus) : gris, comme une sonde qui n'a pas encore de
            quoi répondre. */}
        <span aria-hidden="true" style={{color:muetsTr?C.warn:aucunEmailDeSuivi?C.muted:(C.ok||C.accent),display:'flex'}}><Icon name={muetsTr?'alert':aucunEmailDeSuivi?'clock':'check'} size={14}/></span>
        Réception des emails{muetsTr>0 ? ` · ${muetsTr} transporteur${muetsTr>1?'s':''} silencieux`
          : aucunEmailDeSuivi ? ' · aucun email de suivi reçu pour l’instant' : ' · tout arrive'}
      </summary>
      <div style={{marginTop:8,border:`1px solid ${C.border}`,background:C.card,borderRadius:10,padding:'10px 12px'}}>{detail}</div>
    </details>
  );
}
function PeriodePicker({ value, onChange, compact = false }) {
  const [open,setOpen] = useState(false);
  const [mode,setMode] = useState('mois');
  const localDate = d => d ? `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}` : '';
  const now = new Date();
  const [mois,setMois] = useState(()=>localDate(value?.from || now).slice(0,7));
  const [debut,setDebut] = useState(()=>localDate(value?.from));
  const [fin,setFin] = useState(()=>localDate(value?.to));
  const [erreur,setErreur] = useState('');
  const panneauId = React.useId();
  const choisir = (from,to,label) => { onChange({from,to,label});setOpen(false);setErreur(''); };
  const choisirMois = m => {
    if (!/^\d{4}-\d{2}$/.test(m) || m>localDate(now).slice(0,7)) {setErreur('Choisis un mois passé ou le mois en cours.');return;}
    const [y,n]=m.split('-').map(Number);
    if(n<1 || n>12 || y<2000){setErreur('Choisis un mois valide.');return;}
    choisir(new Date(y,n-1,1),new Date(y,n,0),`${MOIS_FR[n-1]} ${y}`);
  };
  const appliquer = () => {
    if(mode==='mois')return choisirMois(mois);
    if(!debut||!fin||debut>fin){setErreur('La date de fin doit suivre la date de début.');return;}
    const date = v => {const [y,m,d]=v.split('-').map(Number);return new Date(y,m-1,d);};
    choisir(date(debut),date(fin));
  };
  const preset = k => {
    if(k==='mois')return choisirMois(localDate(now).slice(0,7));
    if(k==='dernier'){const d=new Date(now.getFullYear(),now.getMonth()-1,1);return choisirMois(localDate(d).slice(0,7));}
    const jours=k==='j7'?7:30;
    choisir(new Date(now.getFullYear(),now.getMonth(),now.getDate()-jours+1),now,`${jours} derniers jours`);
  };
  const chip = {border:`1px solid ${C.border}`,background:'transparent',color:C.text,borderRadius:8,padding:'6px 10px',fontSize:12,fontWeight:500,cursor:'pointer',whiteSpace:'nowrap',flexShrink:0};
  return <div className="vrm-period" style={{marginBottom:10}}>
    <div className="vrm-rangee" style={{display:'flex',gap:6,alignItems:'center'}}>
      <button type="button" onClick={()=>{setOpen(v=>!v);setErreur('');}} aria-expanded={open} aria-controls={panneauId} style={{...chip,display:'inline-flex',alignItems:'center',gap:6}}><Icon name="calendar" size={14}/>{libellePeriode(value)}</button>
      {!compact && <><button type="button" onClick={()=>preset('mois')} style={chip}>Ce mois</button>
      <button type="button" onClick={()=>preset('dernier')} style={chip}>Mois dernier</button></>}
      {value && <button className="vrm-icon-control" type="button" aria-label="Effacer la période" onClick={()=>{onChange(null);setOpen(false);}} style={chip}><Icon name="close" size={14}/></button>}
    </div>
    {open && <div id={panneauId} className="vrm-period-panel" style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,padding:12,marginTop:8}}>
      <div style={{display:'flex',gap:6,marginBottom:12,flexWrap:'wrap'}}>{compact && <><button type="button" onClick={()=>preset('mois')} style={chip}>Ce mois</button><button type="button" onClick={()=>preset('dernier')} style={chip}>Mois dernier</button></>}<button type="button" onClick={()=>preset('j7')} style={chip}>7 jours</button><button type="button" onClick={()=>preset('j30')} style={chip}>30 jours</button></div>
      <div role="group" aria-label="Choix de période" style={{display:'flex',gap:8,marginBottom:10}}>
        <button type="button" aria-pressed={mode==='mois'} onClick={()=>setMode('mois')} style={{...chip,fontWeight:mode==='mois'?700:400}}>Un mois</button>
        <button type="button" aria-pressed={mode==='dates'} onClick={()=>setMode('dates')} style={{...chip,fontWeight:mode==='dates'?700:400}}>Deux dates</button>
      </div>
      {mode==='mois' ? <label style={{display:'block',fontSize:12,color:C.muted}}>Mois<input aria-label="Mois de la période" type="month" max={localDate(now).slice(0,7)} value={mois} onChange={e=>setMois(e.target.value)} style={{display:'block',width:'100%',marginTop:6,padding:8,border:`1px solid ${C.border}`,borderRadius:8,background:C.bg,color:C.text}}/></label>
        : <div style={{display:'grid',gridTemplateColumns:'repeat(2,minmax(0,1fr))',gap:8}}>
          <label style={{fontSize:12,color:C.muted}}>Du<input aria-label="Début de la période" type="date" value={debut} onChange={e=>setDebut(e.target.value)} style={{display:'block',width:'100%',minWidth:0,marginTop:6,padding:8,border:`1px solid ${C.border}`,borderRadius:8,background:C.bg,color:C.text}}/></label>
          <label style={{fontSize:12,color:C.muted}}>Au<input aria-label="Fin de la période" type="date" value={fin} min={debut||undefined} onChange={e=>setFin(e.target.value)} style={{display:'block',width:'100%',minWidth:0,marginTop:6,padding:8,border:`1px solid ${C.border}`,borderRadius:8,background:C.bg,color:C.text}}/></label>
        </div>}
      {erreur && <p role="alert" style={{fontSize:12,color:C.danger}}>{erreur}</p>}
      <button type="button" className="vrm-button" onClick={appliquer} style={{marginTop:10,background:C.accent,color:C.onAccent,border:0}}>Appliquer</button>
    </div>}
  </div>;
}

function EmptyState({ icon, title, desc, action }) {
  return (
    <div className="vrm-empty-state" style={{textAlign:'center',padding:'34px 20px',background:C.card,border:`1px solid ${C.border}`,borderRadius:12,boxShadow:C.shadow||'none'}}>
      <div style={{width:56,height:56,margin:'0 auto 12px',borderRadius:8,background:`${C.accent}12`,display:'flex',alignItems:'center',justifyContent:'center',fontSize:26}}>{icon}</div>
      <div style={{fontSize:15,fontWeight:700,color:C.text,letterSpacing:-0.3}}>{title}</div>
      {desc && <div style={{fontSize:12,color:C.muted,marginTop:5,lineHeight:1.5,maxWidth:340,marginLeft:'auto',marginRight:'auto'}}>{desc}</div>}
      {action && <div style={{marginTop:14}}>{action}</div>}
    </div>
  );
}

// `icon` accepte soit un nom d'icône au trait (même jeu que la barre du bas —
// l'écran et son onglet portent alors exactement le même symbole), soit un
// emoji pour les écrans qui n'ont pas d'onglet dédié.
// ── « TOUT SUR LE N° » : LE BLOC DE LA RECHERCHE (21 octobre) ──────────────
// Rend ce que `toutSurLeNumero` (src/rechercheNumero.js) a trouvé PAR IDENTITÉ.
// Aucune couleur (§7) sauf le rouge des deux paires présentes sous ce N° (§5).
// Chaque ligne mène à son écran. `numData` absent = lecture en cours.
function ToutSurLeNumero({ q, numData, comptes, onNav, onStock, onChercher }) {
  const lecture = !numData;
  const nd = numData || {};
  const numeros = load('vinted_annonce_numeros', {}) || {};
  const cloud = isCloudReady();
  const fichesLues = cloud || Object.keys(numeros).length ? numeros : null;
  const shipDone = load('vinted_ship_done', {}) || {};
  const liensLbc = load('vrm_lbc_liens', {}) || {};
  const series = [prefixeNumeros(), archiveNumeros()];
  const lu = (v) => (v === undefined ? null : v);
  const rn = toutSurLeNumero(q, {
    fiches: fichesLues, pool: cloud ? load('vinted_used_numeros', null) : null,
    enLigne: lu(nd.enLigne), aConfirmer: nd.aConfirmer || null, masquees: nd.masquees || null,
    comptesOk: comptesRecherche(comptes),
    ventes: lu(nd.ventes), txnItem: lu(nd.txnItem),
    saleOv: load('vinted_sale_overrides', {}) || {},
    bordereaux: lu(nd.bordereaux),
    imprimes: load('vinted_bords_printed', {}) || {}, postes: shipDone,
    lbcVentes: lu(nd.lbcVentes), ebayCommandes: lu(nd.ebayCommandes), ebayAnnonces: lu(nd.ebayAnnonces),
    // « Mes meubles » d'abord (rangement que Julien tient à la main, synchronisé),
    // puis la pièce 3D. Un N° rangé dans un meuble est TROUVÉ même si la pièce
    // n'est pas lue.
    plan: ((load('vrm_meubles', []) || []).length ? (lu(nd.plan) || {}) : lu(nd.plan)),
    archive: archiveNumeros(),
  }, {
    cleNum, conflits: conflitsDeNumeros,
    ouStock: (plan, k) => { const m = ouDansMeubles(k); if (m) return { itemId: 'meuble:' + m.meuble.id, key: String(m.i), itemName: m.meuble.name, nom: m.libelle, roomName: '' }; return ouEstNumero(plan, k); },
    numEbayLigne: numLigneEbay,
    numEbayAnnonce: (a) => numEbayLu(a && a.sku, a && a.itemId, null, a && a.depuis),
    numLbc: (v) => numeroLbcIdentite(v, nd.lbcItems || null, liensLbc),
    aPoster: (o) => aExpedier(o) && !shipDone[String(o.transaction_id)],
    // Posté = le colis est parti (transit, relais, livré, finalisé) — la
    // même étiquette que la carte de la vente (`etapeVente`, §11).
    expediee: (o) => etapeVente(o, { poste: (x) => !!shipDone[String(x.transaction_id)] }).step >= 2,
    revenue: (o) => classifyOrderStatus(o && o.status) === 'cancelled' && !/exp[eé]di|achemin|livr|remis|d[eé]pos/i.test((o && o.status) || ''),
  }, series);
  if (rn.etat === 'invalide') return null;
  const k = rn.cle;
  const jour = (d) => { const t = new Date(d); return isNaN(t.getTime()) ? '' : t.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' }); };
  const lien = { minHeight: 44, background: 'transparent', border: 0, padding: 0, color: C.text, textDecoration: 'underline', cursor: 'pointer', fontFamily: 'inherit', fontSize: 13 };
  const ligne = (cle, attrs, titre, detail, onClick) => (
    <button key={cle} type="button" className="vrm-tout-num-ligne" {...attrs} onClick={onClick}
      style={{ width: '100%', minHeight: 44, display: 'flex', alignItems: 'center', gap: 10, padding: '8px 10px', marginTop: 6, background: C.card, border: `1px solid ${C.border}`, borderRadius: 10, cursor: 'pointer', fontFamily: 'inherit', textAlign: 'left', color: C.text }}>
      <span style={{ flex: 1, minWidth: 0 }}>
        <span style={{ display: 'block', fontSize: 13, fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{titre}</span>
        {detail && <span style={{ display: 'block', fontSize: 12, color: C.muted, marginTop: 2 }}>{detail}</span>}
      </span>
      <span aria-hidden="true" style={{ fontSize: 17, color: C.muted }}>›</span>
    </button>
  );
  const titreSec = (t) => <div style={{ fontSize: 11, fontWeight: 700, color: C.muted, textTransform: 'uppercase', letterSpacing: 0.4, margin: '12px 2px 2px' }}>{t}</div>;
  const ETAT_ANN = { 'en-ligne': 'En ligne sur Vinted', 'a-confirmer': 'À confirmer (dernière lecture ancienne)', masquee: 'Masquée par Vinted, toujours chez toi', 'plus-en-ligne': 'Plus en ligne', passu: 'Annonces pas encore lues' };
  const ETAT_BORD = { pret: 'Prêt à imprimer', imprime: 'Imprimé', poste: 'Posté', attente: 'En attente du PDF' };
  const { vinted, lbc, ebay } = rn.ventes;
  const rien = rn.etat === 'rien';
  const rienDautre = !rn.annonces.length && !vinted.length && !lbc.length && !ebay.length && !rn.annoncesEbay.length && !rn.stock && !rn.reattribues.length;
  return (
    <div data-tout-num={k} data-tout-etat={lecture && rn.etat !== 'trouve' ? 'lecture' : rn.etat} data-tout-lecture={lecture ? '1' : '0'} style={{ marginTop: 10, padding: '10px 12px', background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12 }}>
      <div style={{ fontSize: 15, fontWeight: 700, color: C.text }}>Tout sur le N°{k}</div>
      {rn.ancienNumero && <div style={{ fontSize: 12, color: C.muted, marginTop: 2 }}>Un ancien numéro (d'avant la remise à zéro) : il ne désigne que l'histoire.</div>}
      {rn.double && (
        <div data-tout-double="1" role="alert" style={{ marginTop: 8, padding: '8px 10px', borderRadius: 8, border: `1px solid ${C.danger}`, color: C.danger, fontSize: 13, fontWeight: 600 }}>
          Deux paires présentes portent le N°{k}. Vérifie les cartons avant d'imprimer un bordereau.
          <button type="button" onClick={() => onNav('cat_annonces')} style={{ ...lien, display: 'block', marginTop: 4, color: C.danger }}>Voir dans Annonces</button>
        </div>
      )}
      {rn.reattribues.map((r) => (
        <div key={'r' + r.id + r.sens} data-tout-reattribue={r.sens} style={{ marginTop: 8, fontSize: 13, color: C.text }}>
          {r.sens === 'parti'
            ? <>Le N°{r.de} a été remplacé (doublon réglé) : « {r.title || 'un article'} » porte maintenant le <b>N°{r.vers}</b>. </>
            : <>Ce numéro remplace le N°{r.de} (doublon réglé){r.ecrit ? '.' : ' — pas encore écrit sur le carton.'}</>}
          {r.sens === 'parti' && <button type="button" onClick={() => onChercher(r.vers)} style={lien}>Voir le N°{r.vers}</button>}
        </div>
      ))}
      {rn.annonces.length > 0 && titreSec('L\'article')}
      {rn.annonces.map((a) => ligne('a' + a.id, { 'data-tout-annonce': a.id, 'data-tout-annonce-etat': a.etat }, a.title || '(sans titre)', ETAT_ANN[a.etat] + (a.price ? ' · ' + prixCourt(String(a.price).replace(',', '.')) : ''), () => onNav('cat_annonces')))}
      {(vinted.length + lbc.length + ebay.length + rn.annoncesEbay.length) > 0 && titreSec('Ventes et autres plateformes')}
      {vinted.map((o) => ligne('v' + o._tx, { 'data-tout-vente': 'vinted', 'data-tout-tx': o._tx }, o.title || '(sans titre)', `Vente Vinted · ${etapeVente(o, { poste: (x) => !!shipDone[String(x.transaction_id)] }).label}${o.date ? ' · ' + jour(o.date) : ''}`, () => onNav('cat_ventes')))}
      {lbc.map((v) => ligne('l' + v._id, { 'data-tout-vente': 'leboncoin' }, v.title || '(sans titre)', `Vente Leboncoin · ${lbcAnnulee(v) ? 'annulée' : lbcFinalisee(v) ? 'finalisée' : 'en cours'}${v.price != null ? ' · ' + lbcEuro(v.price) : ''}`, () => onNav('plat_leboncoin')))}
      {ebay.map((c) => ligne('e' + c.orderId, { 'data-tout-vente': 'ebay' }, ((c.lineItems || [])[0] || {}).title || 'Commande eBay', `Vente eBay · ${commandeEbayEngagee(c) ? 'payée' : 'annulée ou remboursée'}${c.creationDate ? ' · ' + jour(c.creationDate) : ''}`, () => onNav('ebay_ventes')))}
      {rn.annoncesEbay.map((a) => ligne('ea' + a.itemId, { 'data-tout-annonce-ebay': String(a.itemId) }, a.title || 'Annonce eBay', 'En vente sur eBay', () => onNav('ebay_annonces')))}
      {rn.bordereaux.length > 0 && titreSec('Bordereau')}
      {rn.bordereaux.map((b) => ligne('b' + b.tx, { 'data-tout-bord': b.tx, 'data-tout-bord-etat': b.etat }, ETAT_BORD[b.etat], 'Colis de la vente Vinted', () => onNav('cat_bord')))}
      {(rn.stock || rn.annonces.length > 0) && titreSec('Stock')}
      {rn.stock
        ? ligne('s', { 'data-tout-stock': rn.stock.itemName || 'range' }, `Rangé : ${rn.stock.itemName || 'un meuble'}`, [rn.stock.roomName, rn.stock.nom].filter(Boolean).join(' · '), () => onStock(k))
        : rn.annonces.length > 0 && <div data-tout-stock="" style={{ fontSize: 13, color: C.muted, marginTop: 4 }}>{rn.manques.includes('ton Stock') ? 'Stock pas encore lu.' : 'Pas rangé dans le Stock.'}</div>}
      {rn.etat === 'trouve' && rienDautre && rn.servi &&
        <div data-tout-servi="1" style={{ fontSize: 13, color: C.text, marginTop: 8 }}>Ce numéro a déjà servi, mais aucune fiche ne le porte aujourd'hui.</div>}
      {rien && <div data-tout-rien="1" style={{ fontSize: 13, color: C.text, marginTop: 8 }}>Le N°{k} n'a jamais servi.</div>}
      {!rien && rn.manques.length > 0 && (
        <div data-tout-manques={rn.manques.length} style={{ fontSize: 12, color: C.muted, marginTop: 8 }}>
          {lecture ? 'Lecture en cours…' : `Pas pu lire : ${rn.manques.join(', ')}.`}{rn.etat === 'passu' && !lecture ? ' Rien trouvé dans le reste — réessaie dans un instant.' : ''}
        </div>
      )}
      {rn.ancien && (
        <button type="button" data-tout-ancien={rn.ancien} onClick={() => onChercher(rn.ancien)} style={{ ...lien, display: 'block', marginTop: 4 }}>
          L'ancien N°{rn.ancien} existe aussi (d'avant la remise à zéro) — le voir
        </button>
      )}
    </div>
  );
}
// (26 oct.) Le titre de la barre du haut (téléphone), posé par la coque à chaque
// rendu : un grand titre d'écran IDENTIQUE se tait sur téléphone (§7, un mot écrit
// deux fois à 60 px d'écart). Un titre différent (sous-écran de Réglages…) reste.
let TITRE_BARRE = '';
function ScreenHead({ icon, title, desc, right }) {
  const line = typeof icon === 'string' && ICON_PATHS[icon];
  // ⚠️ UNE MANCHETTE, PAS UN EN-TÊTE DE TABLEAU DE BORD. Le titre était une
  // ligne de 23 px avec une pastille ronde teintée devant — le gabarit de tous
  // les outils SaaS. Ici : un surtitre en capitales espacées, un titre large et
  // serré, et un FILET D'ENCRE qui ferme le bloc. C'est ce filet, plus que la
  // taille, qui fait lire « page composée » au lieu de « widget ».
  return (
    /* ⚠️ TROIS ÉLÉMENTS DÉCORATIFS ONT SAUTÉ : le trait d'accent flottant, le
       titre à 38 px et le filet d'ENCRE de 2 px qui barrait l'écran. Mis bout à
       bout, ça faisait 90 px de haut pour porter un seul mot, sur chaque écran,
       tous les jours. L'icône rejoint le titre sur sa ligne (elle nomme déjà
       l'écran dans la barre de navigation) et le filet redevient une simple
       séparation. Mesuré : 40 px rendus au contenu, en haut de chaque page. */
    /* (16 oct.) GRAND TITRE : l'échelle typographique de l'app est posée une
       fois (index.html, `--vrm-t-*`) ; taille, graisse et marges vivent dans
       `.vrm-screen-head` (styles-coque.css). Plus de filet sous le titre. */
    <div className={"vrm-screen-head" + (title && title === TITRE_BARRE ? " vrm-screen-head-doublon" : "")}>
      {/* ⚠️ LA RANGÉE DU TITRE RÉSERVE LA PLACE DE L'ÎLE D'ACTIONS. Depuis
          qu'elle flotte en haut à droite (fixe), les boutons qu'un écran pose
          sur sa propre ligne de titre passaient DESSOUS : sur Factures,
          « ⚙ Réglages » disparaissait derrière (vu en capture). Le filet de
          séparation, lui, garde toute la largeur. */}
      <div className="vrm-tete-row">
        <div className="vrm-screen-head-titre">
          {line
            ? <span aria-hidden="true" style={{display:'flex',color:C.muted,flexShrink:0}}><Icon name={icon} size={20}/></span>
            : (icon ? <span aria-hidden="true" style={{fontSize:18}}>{icon}</span> : null)}
          <h2 className="vrm-display" style={{color:C.text}}>{title}</h2>
          {/* ⚠️ LA DESCRIPTION D'ÉCRAN N'EST PLUS AFFICHÉE. Julien : « il y a trop
              d'informations partout, c'est horrible ». Ce paragraphe explique ce
              que fait l'écran — on le lit UNE fois, puis c'est du bruit tous les
              jours, en haut de chaque page, avant le moindre contenu utile.
              Le texte reste passé par les appelants (rien à défaire si on veut
              le remettre, par exemple pour un nouvel utilisateur). */}
        </div>
        {/* ⚠️ `maxWidth:100%` : sans lui, une rangée de boutons ne pouvait pas
            revenir à la ligne sur téléphone (Factures débordait de 300 px sur
            le côté — mesuré le 30 sept.). */}
        {right && <div style={{flexShrink:0,maxWidth:'100%'}}>{right}</div>}
      </div>
    </div>
  );
}

// ── NOTIFICATIONS (toasts) ─────────────────────────────────────────────────
// Remplace les alert() du navigateur : une boîte système bloque l'app, coupe le
// geste en cours et fait « site web des années 2000 ». Ici : un bandeau discret
// en bas de l'écran, qui s'empile et disparaît tout seul.
// ⚠️ Un toast ne remplace PAS une confirmation : il ne recueille aucune
// décision. Pour ça, voir askConfirm / askText plus haut.
let _toasts = [];
let _toastId = 0;
const _toastSubs = new Set();
const _emitToasts = () => { _toastSubs.forEach(f => { try { f([..._toasts]); } catch (_) {} }); };
const onToasts = (fn) => { _toastSubs.add(fn); fn([..._toasts]); return () => _toastSubs.delete(fn); };
const dismissToast = (id) => { _toasts = _toasts.filter(t => t.id !== id); _emitToasts(); };
// type : 'ok' | 'err' | 'info'. Le ton est déduit du texte quand il n'est pas
// précisé, pour que les appels existants restent courts.
const toast = (msg, type) => {
  const text = String(msg == null ? '' : msg);
  if (!text.trim()) return;
  const t = type || (/^(⚠|❌|erreur|échec|impossible|invalide)/i.test(text.trim()) ? 'err'
                    : /^(✓|✅)/.test(text.trim()) ? 'ok' : 'info');
  const id = ++_toastId;
  // Le même message redit (un réglage cliqué plusieurs fois) remplace le précédent :
  // quatre bulles identiques empilées ne disent rien de plus qu'une (§7).
  _toasts = [..._toasts.filter(x => x.text !== text).slice(-3), { id, text, type: t }];
  _emitToasts();
  setTimeout(() => dismissToast(id), t === 'err' ? 6000 : 3800);
};

// ── DÉFILEMENT PARTOUT (K1, 30 septembre) ────────────────────────────────────
// Plainte de Julien : « je ne peux pas descendre sur mon ordi, je suis obligé
// d'utiliser la barre glissante, mon pavé tactile ne marche pas ». MESURÉ : dans
// la coque, c'est `<main>` qui défile, pas le document. Une molette / un pavé
// tactile envoie l'événement à ce qui est SOUS le curseur — dans la marge entre
// le rail et la colonne, dans la bande de droite ou sur le rail, aucun ancêtre
// ne défile : 0 px, alors que la barre glissante de `<main>` marche.
// ⇒ Un événement que personne ne peut absorber est renvoyé à `<main>`.
// ⚠️ On ne vole RIEN : un conteneur défilable sous le curseur (fiche, liste,
// modale) garde la main ; au-dessus d'une MODALE plein écran on ne fait
// défiler rien derrière ; Ctrl+molette (zoom) passe tel quel.
function DefilementPartout() {
  React.useEffect(() => {
    const peutDefiler = (el, dy, dx) => {
      const s = getComputedStyle(el);
      if (Math.abs(dy) >= Math.abs(dx)) return /(auto|scroll)/.test(s.overflowY) && el.scrollHeight > el.clientHeight + 1;
      return /(auto|scroll)/.test(s.overflowX) && el.scrollWidth > el.clientWidth + 1;
    };
    const onWheel = (e) => {
      if (e.defaultPrevented || e.ctrlKey) return;
      const main = document.querySelector('main[data-defile]');
      if (!main) return;
      for (let el = e.target; el && el !== document.body && el !== document.documentElement; el = el.parentElement) {
        if (el === main) return;                       // le navigateur s'en charge
        if (peutDefiler(el, e.deltaY, e.deltaX)) return; // un autre conteneur défile
        if (getComputedStyle(el).position === 'fixed') {
          const r = el.getBoundingClientRect();
          if (r.width >= window.innerWidth - 2 && r.height >= window.innerHeight - 2) return; // modale
        }
      }
      if (Math.abs(e.deltaY) < Math.abs(e.deltaX)) return;
      const f = e.deltaMode === 1 ? 16 : e.deltaMode === 2 ? main.clientHeight : 1;
      main.scrollBy({ top: e.deltaY * f });
    };
    window.addEventListener('wheel', onWheel, { passive: true });
    return () => window.removeEventListener('wheel', onWheel);
  }, []);
  return null;
}

function Toaster() {
  const [list, setList] = React.useState([]);
  React.useEffect(() => onToasts(setList), []);
  // (23 oct.) AU-DESSUS de toute feuille, et EN HAUT de l'écran quand une feuille
  // est ouverte. À 210 sous la coque, un message dit depuis une feuille (« Échec
  // de la suppression — réessaie », « Ces bordereaux n'ont plus leur PDF… »)
  // passait SOUS elle : rien n'était dit. Et en bas il couvrirait le pied de la
  // feuille (« Annuler / Supprimer »). Banc `feuilles-coque.cjs`.
  const enHaut = React.useSyncExternalStore(abonnerFeuilles, uneFeuilleOuverte);
  if (!list.length) return null;
  return (
    <div className="vrm-toasts" data-toasts-place={enHaut ? 'haut' : 'bas'} role="status" aria-live="polite" aria-atomic="false" style={{position:'fixed',left:0,right:0,...(enHaut ? {top:'calc(12px + env(safe-area-inset-top))'} : {bottom:'calc(92px + env(safe-area-inset-bottom))'}),zIndex:Z_MESSAGES,
      display:'flex',flexDirection:'column',alignItems:'center',gap:8,padding:'0 14px',pointerEvents:'none'}}>
      {list.map(t => {
        const col = t.type==='err' ? C.danger : t.type==='ok' ? INV_STATUS.online.color : C.text;
        return (
          <button className="vrm-toast" data-tone={t.type} key={t.id} type="button" title="Fermer ce message" onClick={()=>dismissToast(t.id)}
            style={{pointerEvents:'auto',maxWidth:520,width:'100%',textAlign:'left',cursor:'pointer',fontFamily:'inherit',
              display:'flex',alignItems:'flex-start',gap:9,padding:'11px 14px',borderRadius:10,
              background:C.card,border:`1px solid ${t.type==='info'?C.border:col+'66'}`,
              boxShadow:C.shadowLg||'0 8px 24px rgba(0,0,0,.2)',
              animation:'cancaleToast .26s cubic-bezier(.32,.72,0,1) both'}}>
            <span className="vrm-toast-icon" aria-hidden="true" style={{color:col}}><Icon name={t.type==='err'?'alert':t.type==='ok'?'check':'info'} size={18}/></span>
            <span style={{fontSize:13,fontWeight:500,color:C.text,lineHeight:1.45,whiteSpace:'pre-wrap'}}>{t.text}</span>
          </button>
        );
      })}
    </div>
  );
}

function TopProgress() {
  const [busy, setBusy] = React.useState(false);
  const [pct, setPct] = React.useState(0);
  const [show, setShow] = React.useState(false);
  React.useEffect(() => onBusy(setBusy), []);
  React.useEffect(() => {
    let t;
    if (busy) {
      setShow(true); setPct(p => (p > 0 && p < 90 ? p : 8));
      // Progression qui s'essouffle : jamais 100 % tant que ça charge.
      t = setInterval(() => setPct(p => (p >= 90 ? 90 : p + Math.max(0.6, (90 - p) * 0.08))), 180);
    } else {
      setPct(100);
      t = setTimeout(() => { setShow(false); setPct(0); }, 340);
    }
    return () => { clearInterval(t); clearTimeout(t); };
  }, [busy]);
  if (!show) return null;
  return (
    <div aria-hidden="true" style={{position:'fixed',top:0,left:0,right:0,height:3,zIndex:200,pointerEvents:'none',background:'transparent'}}>
      <div style={{
        height:'100%', width:`${pct}%`,
        background:`linear-gradient(90deg, ${C.accent}, ${C.blue||C.accent})`,
        boxShadow:`0 0 8px ${C.accent}88`,
        borderRadius:'0 999px 999px 0',
        transition:'width .22s ease, opacity .3s ease',
        opacity: pct>=100 ? 0 : 1,
      }}/>
    </div>
  );
}

// ── LE SHELL D'ORDINATEUR ───────────────────────────────────────────────────
// ⚠️ Julien : « le rendu est presque pareil, je veux quelque chose qui
// révolutionne ». Le vrai problème n'était ni les couleurs ni la police : sur
// son écran de 1440 px, l'app était une app MOBILE ÉTIRÉE — une carte de
// 1170 px pour porter trois mots, la navigation EN BAS comme sur un téléphone,
// et 350 px de vide sous le contenu (constaté en capture à 1440×900).
// Aucune retouche de teinte ne corrige ça : c'est la FORME qui est mobile.
// ➡️ Au-dessus de 1024 px : barre latérale à gauche, largeur de lecture bornée,
//    barre du bas retirée. En dessous : rien ne change, le mobile est intact.
const useOrdinateur = () => {
  const [ord, setOrd] = React.useState(() => {
    try { return window.matchMedia('(min-width: 1024px)').matches; } catch (_) { return false; }
  });
  React.useEffect(() => {
    let mq; try { mq = window.matchMedia('(min-width: 1024px)'); } catch (_) { return; }
    const on = () => setOrd(mq.matches);
    try { mq.addEventListener('change', on); } catch (_) { mq.addListener(on); }
    return () => { try { mq.removeEventListener('change', on); } catch (_) { mq.removeListener(on); } };
  }, []);
  return ord;
};

const NAV_LARGEUR = 160;

// Navigation compacte par plateforme. Les outils partagés restent dans le
// panneau Gestion à gauche ; les sections Vinted sont dans leur plateforme.
function SideBar({ tab, setTab, entreprise }) {
  const outils = [...NAV_GESTION, ...NAV_OUTILS];
  const actif = BAR_GROUPE[tab] || tab;
  const bouton=t=><button key={t.id} type="button" className="vrm-rail-button" aria-label={t.label} title={t.bientot?`${t.label} — bientôt`:t.label} onClick={()=>setTab(t.id)} aria-current={actif===t.id?'page':undefined}><NavigationIcon item={t} size={25}/></button>;
  return <nav className="vrm-sidebar vrm-atelier-rail" aria-label="Navigation principale" style={{width:NAV_LARGEUR,background:C.sidebar||C.chrome,borderRight:`1px solid ${C.chromeLine}`,color:C.onChrome}}>
    <div className="vrm-sidebar-brand"><VrmLogo size={68} anim={false}/><NomEntreprise entreprise={entreprise} className="vrm-sidebar-entreprise"/></div>
    <div className="vrm-rail-scroll">
      <div className="vrm-rail-platforms">{BOTTOM_TABS.map(bouton)}</div>
      <section className="vrm-rail-management-group" aria-label="Gestion"><div className="vrm-rail-section-label">Gestion</div><div className="vrm-rail-management">{outils.map(bouton)}</div></section>
    </div>
    <div className="vrm-rail-bottom"><button type="button" className="vrm-rail-button" aria-label="Paramètres" title="Paramètres" onClick={()=>setTab('settings')} aria-current={tab==='settings'?'page':undefined}><Icon name="gear" size={23}/></button></div>
  </nav>;
}

// ── MENU DES ÉCRANS, EN HAUT À GAUCHE (téléphone) ──────────────────────────
// Julien : « je peux peut-être mettre un menu déroulant à gauche, en haut,
// plutôt que de faire en bas avec le plus ».
// Il a raison sur le fond : « Plus » était un SIXIÈME bouton dans une barre de
// cinq, d'un genre différent des autres (il n'ouvre pas un écran, il ouvre une
// liste) — et il changeait de libellé selon l'écran affiché, donc la barre du
// bas n'avait pas toujours la même tête. Ici : la barre du bas porte les cinq
// écrans du quotidien, un point c'est tout, et LE menu donne accès à tout.
// ⚠️ Sur ordinateur il n'existe pas : la barre latérale montre déjà les neuf
//    écrans d'un coup, un bouton de plus ne ferait que dupliquer.
// ⚠️⚠️ IL NE RÉPÈTE PAS LA BARRE DU BAS. Julien, 21 sept. : « tu mets deux fois
//    Ma journée, Annonces et Ventes ». C'était vrai — le menu déroulait les
//    CINQ onglets du quotidien (`BOTTOM_TABS`) alors qu'ils sont déjà, à un
//    tap, dans la barre du bas juste en dessous. Un menu « Plus » ne porte que
//    ce que la barre ne porte PAS (le motif iOS standard) : les écrans
//    ponctuels (`PLUS_TABS`) et Réglages. Zéro doublon, et tout reste joignable
//    (les cinq du quotidien par la barre, le reste par ici). §7 : on ne dit pas
//    deux fois la même chose sur le même écran.
function MenuEcrans({ tab, setTab, dark = false, bottom = false }) {
  const [open, setOpen] = React.useState(false);
  const declencheur = React.useRef(null);
  const panneau = React.useRef(null);
  React.useEffect(() => { setOpen(false); }, [tab]);
  React.useEffect(() => {
    if (!open) return;
    const frame = requestAnimationFrame(() => panneau.current?.querySelector('[role="menuitem"]')?.focus());
    const clavier = e => {
      if (e.key === 'Escape') { setOpen(false); return; }
      if (e.key !== 'Tab') return;
      const boutons = [...(panneau.current?.querySelectorAll('button') || [])];
      const premier = boutons[0], dernier = boutons[boutons.length - 1];
      if (e.shiftKey && document.activeElement === premier) { e.preventDefault(); dernier?.focus(); }
      else if (!e.shiftKey && document.activeElement === dernier) { e.preventDefault(); premier?.focus(); }
    };
    window.addEventListener('keydown', clavier);
    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener('keydown', clavier);
      declencheur.current?.focus();
    };
  }, [open]);
  const groupes = [
    { titre: bottom?'Autres plateformes':'Plateformes', items: BOTTOM_TABS.filter(t => bottom?t.id==='plat_vestiaire':t.id !== 'journee') },
    { titre: 'Gestion', items: NAV_GESTION },
    // (17 oct., Julien) Plus de « Dans Vinted » (Annonces, Ventes, Achats sont
    // déjà dans l'onglet Vinted) ni d'« Autres outils » : ce qu'ils portaient
    // est rangé dans Statistiques et Comptabilité.
    ...(NAV_OUTILS.length ? [{ titre: 'Autres outils', items: NAV_OUTILS }] : []),
  ];
  // (16 oct.) LISTE GROUPÉE FAÇON iOS : des groupes en cartes arrondies, une
  // rangée par écran (icône neutre · libellé · chevron), filets fins en retrait.
  // L'écran courant porte la teinte d'accent et une coche — plus d'aplat bleu.
  // Le dessin vit dans `.vrm-sheet` (styles-coque.css).
  // L'en-tête pose sa feuille dans document.body (voir plus bas) ; celle de la
  // barre du bas reste où elle est.
  const poserFeuille = bottom ? (x) => x : (x) => createPortal(x, document.body);
  const rangee = (t, on, onClick) => (
    <button key={t.id} type="button" role="menuitem" className="vrm-sheet-row" onClick={onClick} aria-current={on?'page':undefined}>
      <span className="vrm-sheet-ic"><NavigationIcon item={t} size={19}/></span>
      <span className="vrm-sheet-lib">{t.label}</span>
      {t.bientot && <span data-bientot="" className="vrm-sheet-badge">Bientôt</span>}
      <span aria-hidden="true" className="vrm-sheet-fin"><Icon name={on?'check':'chevron'} size={on?17:16}/></span>
    </button>
  );
  return (
    <>
      <button ref={declencheur} type="button" onClick={()=>setOpen(o=>!o)} className={bottom?"vrm-tab vrm-nav-more":"vrm-hbtn"} aria-label={bottom?"Gestion":"Tous les écrans"} aria-expanded={open} aria-current={bottom&&! ['journee','plat_vinted','plat_leboncoin','plat_ebay'].includes(BAR_GROUPE[tab]||tab)?'page':undefined}>
        <span aria-hidden="true" className={bottom?"vrm-tab-ic":undefined} style={{display:'flex'}}><Icon name={open&&!bottom?'close':'menu'} size={bottom?24:22} style={{strokeWidth:1.6}}/></span>{bottom && <span className="vrm-nav-label">Gestion</span>}
      </button>
      {/* (23 oct.) La feuille d'en-tête part dans document.body : rendue DANS
          l'en-tête (sticky, z-index 50 — un contexte d'empilement), elle restait
          SOUS la barre du bas (z-index 60) en paysage et sur iPad — ses dernières
          entrées cachées, la barre non assombrie et touchable. Celle de la barre
          du bas vit déjà au bon étage. Banc `feuilles-coque.cjs`. */}
      {open && poserFeuille(
        <div data-noswipe className="vrm-sheet-voile" onClick={()=>setOpen(false)}>
          {/* Depuis la barre du bas, la feuille MONTE du bas ; depuis l'en-tête,
              elle descend du haut : le geste et le mouvement vont dans le même sens. */}
          <div ref={panneau} className={bottom?"vrm-mobile-menu vrm-sheet vrm-sheet-bas vrm-menu-bottom":"vrm-mobile-menu vrm-sheet vrm-sheet-haut"} onClick={e=>e.stopPropagation()} role="menu" aria-label="Tous les écrans">
            {bottom && <div aria-hidden="true" className="vrm-sheet-poignee"/>}
            <div className="vrm-sheet-tete">
              <span className="vrm-sheet-titre">Ton espace</span>
              <button className="vrm-icon-control vrm-sheet-fermer" type="button" aria-label="Fermer le menu" onClick={()=>setOpen(false)}><Icon name="close" size={18}/></button>
            </div>
            {groupes.map(g => (
              <div className="vrm-menu-group vrm-sheet-groupe" key={g.titre}>
                <div className="vrm-sheet-label">{g.titre}</div>
                <div className="vrm-sheet-carte">
                  {g.items.map(t => rangee(t, tab === t.id, ()=>{ setTab(t.id); setOpen(false); }))}
                </div>
              </div>
            ))}
            <div className="vrm-sheet-groupe">
              <div className="vrm-sheet-carte">
                {rangee({id:'settings',icon:'gear',label:'Réglages'}, tab==='settings', ()=>{ setTab('settings'); setOpen(false); })}
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

// Retrouver sa position après un passage dans un autre écran.
function MemoireDefilement({ ecran }) {
  const positions=React.useRef(new Map());
  React.useLayoutEffect(()=>{
    const main=document.querySelector('.vrm-main');
    if(!main) return;
    const cible=positions.current.get(ecran)||0;
    let position=cible, restauration=cible>0, arrete=false;   // rien à tenir à 0
    // On ne s'arrête pas au premier succès : l'écran peut se raccourcir le temps
    // d'un chargement (le navigateur ramène alors la position à 0). On tient la
    // position 2,5 s, sauf si la personne fait défiler elle-même.
    const restaurer=()=>{ if(!arrete&&restauration&&Math.abs(main.scrollTop-cible)>=2) main.scrollTop=cible; };
    const lire=()=>{ if(!restauration) position=main.scrollTop; };
    const intervenir=()=>{ restauration=false; position=main.scrollTop; };
    main.addEventListener('scroll',lire,{passive:true});
    main.addEventListener('wheel',intervenir,{passive:true});
    main.addEventListener('touchstart',intervenir,{passive:true});
    window.addEventListener('keydown',intervenir);
    main.addEventListener('pointerdown',intervenir,{passive:true});
    // (18 oct.) On réessaie à chaque image tant que le contenu arrive : la zone
    // porte plusieurs enfants (un bandeau de 74 px en tête), observer le premier
    // ne voyait jamais l'écran grandir, et la position retombait à 0.
    let image=0;
    const boucle=()=>{ restaurer(); if(!arrete&&restauration) image=requestAnimationFrame(boucle); };
    boucle();
    const delai=setTimeout(()=>{restauration=false;position=main.scrollTop;cancelAnimationFrame(image);},2500);
    return ()=>{
      arrete=true;clearTimeout(delai);cancelAnimationFrame(image);
      positions.current.set(ecran,position);
      main.removeEventListener('scroll',lire);main.removeEventListener('wheel',intervenir);main.removeEventListener('touchstart',intervenir);window.removeEventListener('keydown',intervenir);main.removeEventListener('pointerdown',intervenir);
    };
  },[ecran]);
  return null;
}

function BottomBar({tab,setTab}) {
  // Se cache quand le clavier est ouvert (saisie dans un champ) : sinon iOS la
  // pousse au milieu de l'écran au-dessus du clavier et la mise en page saute.
  const [kbOpen,setKbOpen]=React.useState(false);
  // Les accès quotidiens restent fixes ; Plus ouvre les plateformes et les outils.
  React.useEffect(()=>{
    // (19 oct.) Seul un champ qui OUVRE UN CLAVIER cache la barre. Une case à
    // cocher, un bouton radio ou un curseur prennent aussi le focus au toucher :
    // la barre disparaissait, l'écran sautait de 22 px pendant le geste, et le
    // toucher retombait à côté (la case ne se cochait pas — banc ebay-programmer).
    const SANS_CLAVIER=/^(checkbox|radio|range|file|button|submit|reset|color|image)$/i;
    const isField=el=>el&&(el.tagName==='TEXTAREA'||el.tagName==='SELECT'||(el.tagName==='INPUT'&&!SANS_CLAVIER.test(el.type||'')));
    const onIn=e=>{ if(isField(e.target)) setKbOpen(true); };
    const onOut=()=>setTimeout(()=>{ if(!isField(document.activeElement)) setKbOpen(false); },80);
    window.addEventListener('focusin',onIn);
    window.addEventListener('focusout',onOut);
    return ()=>{ window.removeEventListener('focusin',onIn); window.removeEventListener('focusout',onOut); };
  },[]);
  return (
    <>
    {/* ⚠️ COQUE APP-SHELL (28 sept.) : la barre n'est PAS `position:fixed`.
       Elle est un frère de `<main>` dans une colonne flex bornée à l'écran, et
       c'est `<main>` qui défile — elle ne peut donc pas « flotter au milieu de
       l'écran » pendant l'inertie iOS. Masquée au clavier par `display:none`.
       (16 oct.) BARRE D'ONGLETS NATIVE : icônes fines, libellé 11 px, l'onglet
       actif prend la teinte d'accent — plus de pastille bleue pleine (§7 : une
       seule couleur, rare). Fond en verre, filet fin. Tout le dessin vit dans
       `.vrm-tabbar` (styles-coque.css) : ici seulement la structure. */}
    <nav className="vrm-mobile-nav vrm-tabbar" aria-label="Navigation principale" style={{display:kbOpen?'none':'flex','--vrm-nav-bg':C.sidebar||C.chrome}}>
      {(()=>{ const actif=BAR_GROUPE[tab]||tab;
        const items=BOTTOM_TABS.filter(t=>t.id!=='plat_vestiaire').map(t=>t.id==='journee'?{...t,label:'Accueil'}:t);
        return items.map(t=>{ const on=actif===t.id; return (
        <button key={t.id} type="button" className="vrm-tab" onClick={()=>setTab(t.id)} aria-label={t.label} aria-current={on?'page':undefined}>
          <span aria-hidden="true" className="vrm-tab-ic"><NavigationIcon item={t} size={22} style={{strokeWidth:on?2:1.6}}/></span>
          <span className="vrm-nav-label">{t.label}</span>
        </button>
      );}); })()}
      <MenuEcrans tab={tab} setTab={setTab} bottom/>
    </nav>
    </>
  );
}

/* ── Sparkline ───────────────────────────────────────── */
function Sparkline({data,color=C.accent,h=60}) {
  if(!data||data.length<2) return null;
  const W=400,H=h;
  const max=Math.max(...data,0.01), min=Math.min(...data,0), range=max-min||1;
  const pts=data.map((v,i)=>`${(i/(data.length-1))*W},${H-((v-min)/range)*(H-10)-5}`).join(' ');
  const area=`0,${H} ${pts} ${W},${H}`;
  const id='g'+color.replace('#','');
  return (
    // ⚠️ preserveAspectRatio="none" a été RETIRÉ : il étirait le dessin
    // horizontalement, donc l'épaisseur du trait variait selon la largeur de
    // l'écran (fin sur mobile, épais sur grand écran). Avec « slice », le tracé
    // garde une épaisseur constante partout.
    <svg width="100%" viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="xMidYMid slice" style={{display:'block'}}>
      <defs><linearGradient id={id} x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor={color} stopOpacity="0.22"/>
        <stop offset="100%" stopColor={color} stopOpacity="0"/>
      </linearGradient></defs>
      <polygon points={area} fill={`url(#${id})`}/>
      <polyline points={pts} fill="none" stroke={color} strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke"/>
    </svg>
  );
}


/* ── Dashboard ───────────────────────────────────────── */
// Détail des ventes d'un mois (affiché au clic sur une barre du graphique)
function MonthDetail({mois,type,C,fmt,catMap,catalog,onClose}){
  // Construit le nom de chaque paire depuis le catalogue (si dispo)
  const catName={};
  (catalog||[]).forEach(p=>{ if(p.name) catName[p.id]=p.name; });
  const ventes=[...(mois.ventes||[])].sort((a,b)=>{
    // tri par date (la plus récente d'abord) selon le type de graphique
    const da=(type==='encaisse'?a.receiveDate:a.saleDate)||'';
    const db=(type==='encaisse'?b.receiveDate:b.saleDate)||'';
    return db.localeCompare(da);
  });
  const totalCA=ventes.reduce((s,v)=>s+(+v.sellPrice||0),0);
  const totalProfit=ventes.reduce((s,v)=>s+((+v.sellPrice||0)-(+v.buyPrice||0)),0);
  return (
    <div style={{marginTop:16,padding:14,background:C.bg,borderRadius:8,border:`1px solid ${C.border}`}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:10}}>
        <span style={{fontSize:13,fontWeight:600,color:C.text}}>{mois.nomComplet} — {ventes.length} vente{ventes.length>1?'s':''}</span>
        <span onClick={onClose} style={{cursor:'pointer',color:C.muted,fontSize:20,fontWeight:500,lineHeight:1}}>×</span>
      </div>
      <div style={{display:'flex',gap:16,marginBottom:12,fontSize:12}}>
        <span style={{color:C.text}}>CA : <b>{fmt(totalCA)}</b></span>
        <span style={{color:C.accent}}>Bénéfice : <b>{fmt(totalProfit)}</b></span>
      </div>
      <div style={{maxHeight:260,overflowY:'auto'}}>
        {ventes.map((v,i)=>{
          const nom=catName[v.productId]||(v.productId?('Paire '+v.productId):'—');
          const dateAff=(type==='encaisse'?v.receiveDate:v.saleDate)||'';
          const benef=(+v.sellPrice||0)-(+v.buyPrice||0);
          return (
            <div key={i} style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'7px 0',borderBottom:`1px solid ${C.border}`,fontSize:12}}>
              <div style={{flex:1,minWidth:0}}>
                <div style={{color:C.text,fontWeight:600,whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>{nom}</div>
                <div style={{color:C.muted,fontSize:11}}>{dateAff}{v.productId?` · n°${v.productId}`:''}</div>
              </div>
              <div style={{textAlign:'right',marginLeft:10}}>
                <div style={{color:C.text,fontWeight:500}}>{fmt(+v.sellPrice||0)}</div>
                <div style={{color:benef>=0?C.accent:C.warn,fontSize:11}}>{benef>=0?'+':''}{fmt(benef)}</div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

