  const [hiddenPts, setHiddenPts] = useState(() => new Set(load('vrm_points_hidden', [])));
  const hidePoint = (nom) => { setHiddenPts(prev => { const n = new Set(prev); n.add(norm2(nom)); save('vrm_points_hidden', [...n]); return n; }); setOpenPoint(null); };
