  // ── VENTES LEBONCOIN PROUVÉES, pour le CA par plateforme du tableau de bord ──
  // §5 : une VENTE Leboncoin n'est comptée que si `isSeller===true` (le détail de
  // transaction le dit) — jamais déduite d'une transaction vue en liste. Lecture
  // seule, `null`/échec ⇒ rien (« rien lu » ne vaut pas « rien »). Même règle que
  // la section « Ventes Leboncoin » de l'écran Ventes (§11) ; ici c'est le seul
  // lecteur côté COQUE, pour alimenter le tableau de bord.
  const [lbcVentes,setLbcVentes]=useState({ ventes:[], inconnues:0 });
  // Trois états : `undefined` pas encore lu · `null` pas su · `true` lu.
  const [lbcCoqueLu,setLbcCoqueLu]=useState(undefined);
  useEffect(()=>{
    const suivi=suivreReceptionLeboncoin({fenetre:window,document,relire:async(estActif)=>{
    try {
      const rows = await lireReceptionLeboncoin(`${SUPABASE_URL}/rest/v1/app_data?id=eq.lbc_ventes&select=data`,sbAuth());
      if (!estActif()) return;
      if (!Array.isArray(rows)) { setLbcCoqueLu(null); return; }
      const obj = (rows && rows[0] && rows[0].data && rows[0].data.ventes) || {};
      const arr = Object.values(obj);
      // Côté pas encore su, ET non annulées (une transaction annulée est morte :
      // ni comptée ni affichée, sinon « 8 autres » pour 3 vivantes, §7/§11).
      const inc = arr.filter(o => o && o.isSeller == null && !lbcAnnulee(o));
      // ACHATS = `isSeller === false` (jamais déduit, §5) — mêmes champs que les
      // ventes (photo, titre, prix, statut). Avant, ils étaient simplement jetés.
      // `maj` = la dernière fois qu'une transaction Leboncoin a été captée.
      // L'extension ne rafraîchit les ventes QUE sur « Mes transactions » :
      // visiter Leboncoin en général ne suffit pas. On montre donc l'âge des
      // montants (§7 : un chiffre qu'on ne peut pas dater n'est pas fiable).
      const maj = arr.reduce((m, o) => { const t = Date.parse((o && o.at) || '') || 0; return t > m ? t : m; }, 0);
      setLbcVentes({ ventes: arr.filter(o => o && o.isSeller === true), achats: arr.filter(o => o && o.isSeller === false), inconnues: inc.length,
        maj, inconnuesListe: inc.slice().sort((a,b)=>String(b.at||'').localeCompare(String(a.at||''))) });
      setLbcCoqueLu(true);
    } catch (_) { if (!estActif()) return; setLbcCoqueLu(null); /* pas su ⇒ rien : jamais un faux « vendu » */ }

    }});
    suivi.actualiser();
    return ()=>suivi.arreter();
  }, []);
  // CA eBay pour le Tableau de bord / le Collectif : la somme des commandes
  // PAYÉES captées (`caEbayPayees`, la MÊME règle que la carte « payées » de
  // l'écran eBay, §11). `null` tant qu'aucune vente payée n'est captée — le
  // Collectif lit « pas encore de vente », jamais 0 € (§5). Une lecture ratée
  // reste `null` : « pas su » ne vaut pas « zéro vente ».
  const [ebayCa,setEbayCa]=useState(null);
